window.BASAIR_QUESTIONS=window.BASAIR_QUESTIONS.concat([{"id":"s82-14","number":14,"surah":82,"verses":[19],"verseLabel":"الانفطار: 19","question":"كيف يلخص الختام ﴿لَا تَمْلِكُ نَفْسٌ لِنَفْسٍ شَيْئًا﴾ السورة؟","answer":"بعد غرور الإنسان بصورته وقدرته تسقط كل ملكية ونصرة، ويظهر أن الأمر يومئذ لله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص413–427.","url":""}]},{"id":"s83-1","number":1,"surah":83,"verses":[1],"verseLabel":"المطففين: 1","question":"لماذا افتتحت بـ﴿وَيْلٌ لِلْمُطَفِّفِينَ﴾ دون مقدمة؟","answer":"المباغتة تناسب جريمة يتساهل أصحابها في صغر مقدارها؛ فجاء الوعيد أكبر من الجزء المسروق.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص436–452.","url":""}]},{"id":"s83-2","number":2,"surah":83,"verses":[2,3],"verseLabel":"المطففين: 2–3","question":"ما المفارقة في ﴿اكْتَالُوا عَلَى النَّاسِ يَسْتَوْفُونَ... كَالُوهُمْ أَوْ وَزَنُوهُمْ يُخْسِرُونَ﴾؟","answer":"يطلبون حقهم كاملًا ويجعلون حق غيرهم ناقصًا؛ واختلاف حرفي الجر يكشف تمركزهم حول مصلحتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص436–452.","url":""}]},{"id":"s83-3","number":3,"surah":83,"verses":[4,5,6],"verseLabel":"المطففين: 4–6","question":"لماذا عولج التطفيف بسؤال البعث؟","answer":"من استحضر وقوفه لرب العالمين لم يهن عليه جزء من حق الناس؛ فالجريمة الاقتصادية عرض لغياب الحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص453–462.","url":""}]},{"id":"s83-4","number":4,"surah":83,"verses":[6],"verseLabel":"المطففين: 6","question":"ما أثر ﴿يَقُومُ النَّاسُ لِرَبِّ الْعَالَمِينَ﴾؟","answer":"القيام يصور طول الموقف وهيبته، وإضافة الرب إلى العالمين تسقط امتياز المتكبر والمستضعف.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص453–462.","url":""}]},{"id":"s83-5","number":5,"surah":83,"verses":[7,8,9],"verseLabel":"المطففين: 7–9","question":"ما سرّ التعبير بقوله تعالى: ﴿كِتَابَ الْفُجَّارِ لَفِي سِجِّينٍ﴾ ثم ﴿كِتَابٌ مَرْقُومٌ﴾؟","answer":"ذُكرت في ﴿سِجِّينٍ﴾ أقوال في حقيقتها وموضعها، ويجمعها معنى السفل والضيق والحبس؛ ثم يبين ﴿كِتَابٌ مَرْقُومٌ﴾ أن سجل الفجار مثبت معلوم لا يضيع.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص463–484.","url":""}]},{"id":"s83-6","number":6,"surah":83,"verses":[8,19],"verseLabel":"المطففين: 8، 19","question":"لماذا تكرر ﴿وَمَا أَدْرَاكَ﴾ مع سجين وعليين؟","answer":"جاء الاستفهام للتفخيم والتهويل؛ فسِجِّين مما يضيق ويسفل بكتاب الفجار، وعِلِّيّون موضع رفيع لكتاب الأبرار، وحقيقة أمرهما من شؤون الآخرة التي تتجاوز إدراك الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص463–506.","url":""}]},{"id":"s83-7","number":7,"surah":83,"verses":[10,11,12],"verseLabel":"المطففين: 10–12","question":"لماذا وصف المكذب بأنه ﴿مُعْتَدٍ أَثِيمٍ﴾؟","answer":"التكذيب بالجزاء ينبت تجاوز الحدود والإغراق في الإثم؛ فالوصفان يفسران كيف يصل إلى رد الآيات بالأساطير.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص463–484.","url":""}]},{"id":"s83-8","number":8,"surah":83,"verses":[13],"verseLabel":"المطففين: 13","question":"ما دلالة قولهم ﴿أَسَاطِيرُ الْأَوَّلِينَ﴾؟","answer":"ينقلون الوحي من الحاضر الملزم إلى حكايات ماضية، ليعطلوا أثره دون مناقشة حجته.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص463–484.","url":""}]},{"id":"s83-9","number":9,"surah":83,"verses":[14],"verseLabel":"المطففين: 14","question":"ما الصورة في ﴿رَانَ عَلَى قُلُوبِهِمْ﴾؟","answer":"الذنوب كصدأ يتراكم حتى يغطي سطح القلب، فالعجز عن رؤية الحق نتيجة كسب متكرر.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص485–498.","url":""}]},{"id":"s83-10","number":10,"surah":83,"verses":[15],"verseLabel":"المطففين: 15","question":"لماذا كان الحجاب عن الرب عقوبة؟","answer":"لأن أعظم النعيم قربه ورضاه، فناسب من حجب قلبه بالران أن يحجب يومئذ عن الكرامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص485–498.","url":""}]},{"id":"s83-11","number":11,"surah":83,"verses":[18,19,20,21],"verseLabel":"المطففين: 18–21","question":"كيف قابل سجل الأبرار بسجل الفجار؟","answer":"قوبل سِجِّين بعِلِّيّين، ودل المذكور في كل طرف على المحذوف في الآخر على طريق الاحتباك: سفل كتاب الفجار ودركتهم، وعلو كتاب الأبرار ودرجتهم؛ ثم خُص كتاب الأبرار بشهادة المقربين تشريفًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص463–506.","url":""}]},{"id":"s83-12","number":12,"surah":83,"verses":[22,23,24],"verseLabel":"المطففين: 22–24","question":"ما سرّ التعبير في قوله ﴿تَعْرِفُ فِي وُجُوهِهِمْ نَضْرَةَ النَّعِيمِ﴾؟","answer":"جعل النعيم علامة تُقرأ على الوجه، فتحولت لذة الباطن إلى ضياء ظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص507–528.","url":""}]},{"id":"s83-13","number":13,"surah":83,"verses":[25,26],"verseLabel":"المطففين: 25–26","question":"ما دلالة ﴿رَحِيقٍ مَخْتُومٍ خِتَامُهُ مِسْكٌ﴾؟","answer":"الختم يصون الشراب ويضمن خلوصه، ثم تكون آخر رائحته مسكًا؛ فجمع الأمان واللذة وحسن العاقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص507–528.","url":""}]},{"id":"s83-14","number":14,"surah":83,"verses":[26],"verseLabel":"المطففين: 26","question":"لماذا أعقب وصف النعيم بقوله ﴿وَفِي ذَلِكَ فَلْيَتَنَافَسِ الْمُتَنَافِسُونَ﴾؟","answer":"نقل غريزة التنافس من الكيل والربح الدنيوي إلى غاية تستحق السباق ولا تظلم أحدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص507–528.","url":""}]},{"id":"s83-15","number":15,"surah":83,"verses":[27,28],"verseLabel":"المطففين: 27–28","question":"ما الفرق بين الرحيق الممزوج والتسنيم الذي يشرب به المقربون؟","answer":"أصحاب اليمين يمزج شرابهم من عين التسنيم، أما المقربون فأقرب إلى العين يشربون منها أو بها مباشرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص507–528.","url":""}]},{"id":"s83-16","number":16,"surah":83,"verses":[29,30,31,32,33],"verseLabel":"المطففين: 29–33","question":"كيف قلبت الآيات مشهد سخرية المجرمين من المؤمنين؟","answer":"صورت ضحكهم وغمزهم وتفكههم في الدنيا، ثم كشفت أنهم لم يرسلوا حراسًا على الإيمان؛ فبطلت وصايتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص529–543.","url":""}]},{"id":"s83-17","number":17,"surah":83,"verses":[34,35,36],"verseLabel":"المطففين: 34–36","question":"لماذا ختمت بضحك المؤمنين وسؤال ﴿هَلْ ثُوِّبَ الْكُفَّارُ مَا كَانُوا يَفْعَلُونَ﴾؟","answer":"انقلب موضع الضحك، وجاء السؤال تقريرًا لتمام الجزاء: عاد فعلهم إليهم على قدره.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص544–553.","url":""}]},{"id":"s84-1","number":1,"surah":84,"verses":[1,2,3,4,5],"verseLabel":"الانشقاق: 1–5","question":"لماذا تكرر ﴿وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ﴾ للسماء والأرض؟","answer":"الكون كله يسمع ويطيع طاعة مستحقة؛ والتكرار يجعل الانقياد قانونًا يشمل العلو والسفل.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص560–581.","url":""}]},{"id":"s84-2","number":2,"surah":84,"verses":[1],"verseLabel":"الانشقاق: 1","question":"ما الفرق بين افتتاح الانشقاق بـ﴿إِذَا السَّمَاءُ انْشَقَّتْ﴾ وافتتاح الانفطار؟","answer":"الانشقاق يبرز التصدع الظاهر الممتد، أما الانفطار فيوحي بابتداء التفطر؛ وكل لفظ يلائم شبكة صور سورته.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص322–355، وص554–581.","url":""}]},{"id":"s84-3","number":3,"surah":84,"verses":[3,4],"verseLabel":"الانشقاق: 3–4","question":"ما الصورة في مد الأرض وإلقائها ما فيها وتخليها؟","answer":"تصير الأرض بساطًا ممتدًا، وتلفظ ما في جوفها حتى تفرغ؛ وكأنها تؤدي أمانتها كاملة.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص560–581.","url":""}]},{"id":"s84-4","number":4,"surah":84,"verses":[6],"verseLabel":"الانشقاق: 6","question":"ما سرّ التعبير بقوله تعالى: ﴿إِنَّكَ كَادِحٌ إِلَى رَبِّكَ كَدْحًا فَمُلَاقِيهِ﴾؟","answer":"الكدح جهد يشق الجسد؛ وحرف «إلى» يجعل كل حركة في العمر سفرًا حتميًا ينتهي إلى لقاء العمل أو الرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص560–581.","url":""}]},{"id":"s84-5","number":5,"surah":84,"verses":[7,8,9],"verseLabel":"الانشقاق: 7–9","question":"لماذا أوتي السعيد كتابه بيمينه وحوسب حسابًا يسيرًا؟","answer":"اليمين علامة القبول، والحساب اليسير عرض بلا استقصاء مهلك، ثم يعود إلى أهله فرحًا بدل انقطاع الروابط.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص582–592.","url":""}]},{"id":"s84-6","number":6,"surah":84,"verses":[10,11,12],"verseLabel":"الانشقاق: 10–12","question":"لماذا يأخذ الشقي كتابه وراء ظهره؟","answer":"هيئة تجمع الخزي ومحاولة الإخفاء، ثم لا يجد إلا أن يدعو الهلاك ويصلى السعير.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص593–614.","url":""}]},{"id":"s84-7","number":7,"surah":84,"verses":[13,14],"verseLabel":"الانشقاق: 13–14","question":"ما المفارقة بين ﴿كَانَ فِي أَهْلِهِ مَسْرُورًا﴾ ومصيره؟","answer":"سروره كان غافلًا قصيرًا مبنيًا على ظن ألا يرجع، فقابله سرور المؤمن بعد الحساب وهو السرور الباقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص582–614.","url":""}]},{"id":"s84-8","number":8,"surah":84,"verses":[14,15],"verseLabel":"الانشقاق: 14–15","question":"لماذا ردّ على ظنه بـ﴿بَلَى إِنَّ رَبَّهُ كَانَ بِهِ بَصِيرًا﴾؟","answer":"الرؤية الإلهية المستمرة تبطل وهم الإفلات؛ فمن كان منظورًا في الدنيا لا يُترك بلا رجوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص593–614.","url":""}]},{"id":"s84-9","number":9,"surah":84,"verses":[16,17,18],"verseLabel":"الانشقاق: 16–18","question":"ما مناسبة القسم بالشفق والليل والقمر؟","answer":"كلها أحوال انتقال وتدرج من ضوء إلى ظلمة إلى اكتمال، تمهيدًا لقانون انتقال الإنسان من حال إلى حال.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص615–628.","url":""}]},{"id":"s84-10","number":10,"surah":84,"verses":[19],"verseLabel":"الانشقاق: 19","question":"ما سرّ التعبير بقوله تعالى: ﴿لَتَرْكَبُنَّ طَبَقًا عَنْ طَبَقٍ﴾؟","answer":"الطبقات أحوال متراكبة: خلق وحياة وموت وبعث وحساب؛ فلا ثبات للإنسان في مرحلة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص615–628.","url":""}]},{"id":"s84-11","number":11,"surah":84,"verses":[20,21],"verseLabel":"الانشقاق: 20–21","question":"ما المفارقة في ﴿فَمَا لَهُمْ لَا يُؤْمِنُونَ وَإِذَا قُرِئَ عَلَيْهِمُ الْقُرْآنُ لَا يَسْجُدُونَ﴾؟","answer":"بعد انقياد السماء والأرض يبدو امتناع الإنسان شذوذًا؛ فالكون يأذن لربه وهو يرفض السجود.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص560–581، وص629–650.","url":""}]},{"id":"s84-12","number":12,"surah":84,"verses":[22,23],"verseLabel":"الانشقاق: 22–23","question":"ما سرّ التعبير بقوله تعالى: ﴿وَاللَّهُ أَعْلَمُ بِمَا يُوعُونَ﴾؟","answer":"«يوعون» تصور ما يجمعونه ويخفونه في صدورهم كوعاء؛ فعلم الله يحيط بالتكذيب الباطن لا الظاهر فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص629–650.","url":""}]},{"id":"s84-13","number":13,"surah":84,"verses":[24],"verseLabel":"الانشقاق: 24","question":"ما أثر ﴿فَبَشِّرْهُمْ بِعَذَابٍ أَلِيمٍ﴾؟","answer":"استعيرت البشارة لما يسوء تهكمًا وتهديدًا؛ فالخبر الذي استقبلوه بالتكذيب سيأتيهم يقينًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص629–650.","url":""}]},{"id":"s84-14","number":14,"surah":84,"verses":[25],"verseLabel":"الانشقاق: 25","question":"ما سرّ مجيء ﴿لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ﴾ بلا فاء؟","answer":"لأن الاستثناء هنا منقطع بمعنى «لكن» بعد وصف المكذبين، فجاءت الجملة استئنافًا في شأن المؤمنين، ولم تُبنَ على شرط ملفوظ يقتضي الفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص629–650.","url":""}]},{"id":"s85-1","number":1,"surah":85,"verses":[1,2,3],"verseLabel":"البروج: 1–3","question":"لماذا جمع القسم بين السماء ذات البروج واليوم الموعود وشاهد ومشهود؟","answer":"ربط نظام السماء بثبوت الموعد وبمشهد الشهادة، ليضع جريمة الأخدود تحت كون لا يغيب عنه شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص657–687.","url":""}]},{"id":"s85-2","number":2,"surah":85,"verses":[3],"verseLabel":"البروج: 3","question":"لماذا نُكّر ﴿شَاهِدٍ وَمَشْهُودٍ﴾؟","answer":"يفتح اللفظ لصور الشهادة العظيمة كلها، ويضخم الشاهد والمشهد دون حصر يضيّق المعنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص657–687.","url":""}]},{"id":"s85-3","number":3,"surah":85,"verses":[4],"verseLabel":"البروج: 4","question":"ما قوة التعبير ﴿قُتِلَ أَصْحَابُ الْأُخْدُودِ﴾؟","answer":"دعاء عليهم بالهلاك أو خبر بتحققه، يأتي عقب القسم حكمًا قاطعًا قبل تفصيل الجريمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص657–687.","url":""}]},{"id":"s85-4","number":4,"surah":85,"verses":[5],"verseLabel":"البروج: 5","question":"لماذا وُصفت النار بـ﴿ذَاتِ الْوَقُودِ﴾؟","answer":"تشعر بنار معدة متصلة المادة، لا لهب عابر؛ فيظهر قصد التعذيب واستمراره.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص657–687.","url":""}]},{"id":"s85-5","number":5,"surah":85,"verses":[6,7],"verseLabel":"البروج: 6–7","question":"ما المفارقة في جلوسهم على النار وهم شهود؟","answer":"الجالس مطمئن، لكن جلوسهم لمشاهدة التعذيب يكشف برود القسوة؛ وشهادتهم التي حسبوها متعة تصير حجة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص657–687.","url":""}]},{"id":"s85-6","number":6,"surah":85,"verses":[8],"verseLabel":"البروج: 8","question":"لماذا قُصر سبب النقمة على الإيمان بالله العزيز الحميد؟","answer":"الاستثناء يفضح أن «جريمة» المؤمنين فضيلة خالصة، ويقابل ضعفهم بعزة ربهم واستحقاقه الحمد.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص657–687.","url":""}]},{"id":"s85-7","number":7,"surah":85,"verses":[9],"verseLabel":"البروج: 9","question":"ما مناسبة ﴿لَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ﴾ لقصة مستضعفين؟","answer":"من يملك الكون لا يعجز عن نصرتهم أو الاقتصاص لهم؛ فالملك الحقيقي ينقض سلطان المعذبين المؤقت.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص657–687.","url":""}]},{"id":"s85-8","number":8,"surah":85,"verses":[10],"verseLabel":"البروج: 10","question":"لماذا فتح باب التوبة للذين فتنوا المؤمنين بعد هذا الجرم؟","answer":"ليظهر سعة الرحمة، وليجعل إصرارهم بعد إمكان التوبة جريمة ثانية تستحق عذاب الحريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص688–700.","url":""}]},{"id":"s85-9","number":9,"surah":85,"verses":[11],"verseLabel":"البروج: 11","question":"كيف قابلت السورة النار بالجنات التي تجري من تحتها الأنهار؟","answer":"قابلت الحريق بالماء الجاري، والفتنة بالفوز الكبير؛ فانتقل المؤمن من نار لحظة إلى نعيم دائم.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص688–700.","url":""}]},{"id":"s85-10","number":10,"surah":85,"verses":[12],"verseLabel":"البروج: 12","question":"ما دلالة ﴿إِنَّ بَطْشَ رَبِّكَ لَشَدِيدٌ﴾؟","answer":"البطش أخذ بقوة، وإضافته إلى «ربك» تثبيت للنبي: الذي يرعاه قادر على أخذ الطغاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص701–712.","url":""}]},{"id":"s85-11","number":11,"surah":85,"verses":[13,14,15,16],"verseLabel":"البروج: 13–16","question":"لماذا جمعت الصفات: يبدئ ويعيد، الغفور الودود، ذو العرش المجيد، فعال لما يريد؟","answer":"جمعت القدرة على الإعادة والانتقام مع المغفرة والمحبة والملك والمشيئة؛ فلا تُقرأ الشدة منفصلة عن الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص701–712.","url":""}]},{"id":"s85-12","number":12,"surah":85,"verses":[17,18],"verseLabel":"البروج: 17–18","question":"لماذا اختُصر خبر فرعون وثمود في سؤال ﴿هَلْ أَتَاكَ حَدِيثُ الْجُنُودِ﴾؟","answer":"يكفي استدعاء القوتين المشهورتين ليرى المكذبون أن الجموع لا تحمي من بطش الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص713–716.","url":""}]},{"id":"s85-13","number":13,"surah":85,"verses":[19,20],"verseLabel":"البروج: 19–20","question":"ما الصورة في ﴿وَاللَّهُ مِنْ وَرَائِهِمْ مُحِيطٌ﴾؟","answer":"كأنهم داخل دائرة لا منفذ منها؛ فالتكذيب لا يخرجهم من سلطان العلم والقدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص717–720.","url":""}]},{"id":"s85-14","number":14,"surah":85,"verses":[21,22],"verseLabel":"البروج: 21–22","question":"لماذا ختمت بـ﴿قُرْآنٌ مَجِيدٌ فِي لَوْحٍ مَحْفُوظٍ﴾؟","answer":"بعد إحراق الأجساد يثبت أن الحق نفسه مصون، وأن وعيده ووعده محفوظان لا يبطلهما الطغاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص721–724.","url":""}]},{"id":"s86-1","number":1,"surah":86,"verses":[1,2,3],"verseLabel":"الطارق: 1–3","question":"ما سرّ التعبير في قوله ﴿وَمَا أَدْرَاكَ مَا الطَّارِقُ﴾ ثم فسره بالنجم الثاقب؟","answer":"أبهمه أولًا للتشويق والتفخيم، ثم كشف أن القادم الليلي نور نافذ يشق الظلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص732–744.","url":""}]},{"id":"s86-2","number":2,"surah":86,"verses":[3],"verseLabel":"الطارق: 3","question":"ما دلالة وصف النجم بـ﴿الثَّاقِبُ﴾؟","answer":"الثاقب النافذ المضيء؛ فيصور ضوءًا يخترق الحجب، تمهيدًا لإحاطة الحفظ وكشف السرائر.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص732–744.","url":""}]},{"id":"s86-3","number":3,"surah":86,"verses":[4],"verseLabel":"الطارق: 4","question":"ما سرّ التعبير بقوله تعالى: ﴿إِنْ كُلُّ نَفْسٍ لَمَّا عَلَيْهَا حَافِظٌ﴾؟","answer":"أسلوب قصر يجعل الحفظ شاملًا لكل نفس؛ فلا عمل يضيع تحت السماء التي أقسم بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص732–744.","url":""}]},{"id":"s86-4","number":4,"surah":86,"verses":[5],"verseLabel":"الطارق: 5","question":"لماذا أُمر الإنسان أن ينظر ﴿مِمَّ خُلِقَ﴾؟","answer":"يرده من استبعاد البعث إلى بداية يحمل دليلها في نفسه؛ فالذي بدأ الخلق قادر على رده.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص745–755.","url":""}]},{"id":"s86-5","number":5,"surah":86,"verses":[6],"verseLabel":"الطارق: 6","question":"ما أثر وصف الماء بـ﴿دَافِقٍ﴾؟","answer":"أسند الدفق إلى الماء للمبالغة كأنه يندفع بذاته، فصور قوة الحركة في مادة ضعيفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص745–755.","url":""}]},{"id":"s86-6","number":6,"surah":86,"verses":[7],"verseLabel":"الطارق: 7","question":"كيف نفهم ﴿يَخْرُجُ مِنْ بَيْنِ الصُّلْبِ وَالتَّرَائِبِ﴾ بيانيًا؟","answer":"ذكر الأصل وجهين في اتصال النشأة بالرجل والمرأة: امتزاج مائهما في الرحم، أو خروج الماء من بين صلب كل واحد منهما وترائبه؛ والجامع أن أعضاءهما وقواهما تتعاون في تكوين مبدأ الإنسان، فيدل خفاء التكوين ودقته على القدرة على إعادته.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص745–755.","url":""}]},{"id":"s86-7","number":7,"surah":86,"verses":[8],"verseLabel":"الطارق: 8","question":"ما دلالة ﴿إِنَّهُ عَلَى رَجْعِهِ لَقَادِرٌ﴾؟","answer":"التوكيدات تثبت النتيجة بعد دليل الخلق، و«رجعه» تشمل إعادته حيًا بعد الموت.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص756–765.","url":""}]},{"id":"s86-8","number":8,"surah":86,"verses":[9,10],"verseLabel":"الطارق: 9–10","question":"لماذا سمي يوم القيامة ﴿يَوْمَ تُبْلَى السَّرَائِرُ﴾؟","answer":"تُختبر المخبآت وتظهر حقيقتها، فيصبح الباطن المكشوف أساس الحساب لا القشرة الاجتماعية.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص756–765.","url":""}]},{"id":"s86-9","number":9,"surah":86,"verses":[10],"verseLabel":"الطارق: 10","question":"لماذا جمع نفي القوة والناصر؟","answer":"لا قدرة ذاتية تدفع ولا قوة خارجية تنصر؛ فسدت جهتا النجاة اللتان يعتمد عليهما الإنسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص756–765.","url":""}]},{"id":"s86-10","number":10,"surah":86,"verses":[11,12],"verseLabel":"الطارق: 11–12","question":"ما مناسبة القسم بالسماء ذات الرجع والأرض ذات الصدع؟","answer":"رجوع المطر وصدع الأرض بالنبات صورة مشاهدة لدورة الإحياء، فتشهد لإمكان رجع الإنسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص766–776.","url":""}]},{"id":"s86-11","number":11,"surah":86,"verses":[13,14],"verseLabel":"الطارق: 13–14","question":"لماذا وصف القرآن بأنه ﴿قَوْلٌ فَصْلٌ وَمَا هُوَ بِالْهَزْلِ﴾؟","answer":"يفصل الحق عن الباطل ويترتب عليه المصير؛ فنفي الهزل يرد تعامل المكذبين معه كلعب.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص766–776.","url":""}]},{"id":"s86-12","number":12,"surah":86,"verses":[15,16,17],"verseLabel":"الطارق: 15–17","question":"كيف قابلت السورة كيدهم بكيد الله؟","answer":"كيدهم تدبير محدود داخل إحاطة الله، فجاء الإمهال ﴿رُوَيْدًا﴾ تهديدًا هادئًا أشد من العجلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص777–786.","url":""}]},{"id":"s87-1","number":1,"surah":87,"verses":[1],"verseLabel":"الأعلى: 1","question":"لماذا جاء الأمر ﴿سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى﴾ بذكر الاسم؟","answer":"ليجمع تنزيه الذات مع تنزيه كل اسم يُذكر به الرب، وإضافة «ربك» تقرب معنى الرعاية قبل وصف العلو.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص793–809.","url":""}]},{"id":"s87-2","number":2,"surah":87,"verses":[1],"verseLabel":"الأعلى: 1","question":"ما مناسبة ﴿الْأَعْلَى﴾ لمطلع السورة؟","answer":"التسبيح رفع عن النقائص، فجاء اسم الأعلى موافقًا للحركة المعنوية ومهيئًا للنظر في آثار القدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص793–809.","url":""}]},{"id":"s87-3","number":3,"surah":87,"verses":[2,3],"verseLabel":"الأعلى: 2–3","question":"ما دلالة ترتيب ﴿خَلَقَ فَسَوَّى وَالَّذِي قَدَّرَ فَهَدَى﴾؟","answer":"الخلق إيجاد، والتسوية إحكام، والتقدير تحديد، والهداية توجيه كل مخلوق إلى وظيفته؛ تدرج من البنية إلى الغاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص793–809.","url":""}]},{"id":"s87-4","number":4,"surah":87,"verses":[4,5],"verseLabel":"الأعلى: 4–5","question":"لماذا تحول المرعى الأخضر إلى ﴿غُثَاءً أَحْوَى﴾؟","answer":"صورة تختصر دورة النضارة والفناء، فتُري العين أن أجمل ما في الدنيا يصير حطامًا داكنًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص793–809.","url":""}]},{"id":"s87-5","number":5,"surah":87,"verses":[6,7],"verseLabel":"الأعلى: 6–7","question":"كيف يجتمع ﴿سَنُقْرِئُكَ فَلَا تَنْسَى﴾ مع ﴿إِلَّا مَا شَاءَ اللَّهُ﴾؟","answer":"هو وعد بالحفظ، والاستثناء يثبت بقاء الأمر تحت المشيئة الإلهية ويستوعب ما نُسخ تلاوته، لا يفتح باب الشك في البلاغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص10–22.","url":""}]},{"id":"s87-6","number":6,"surah":87,"verses":[7],"verseLabel":"الأعلى: 7","question":"لماذا عقب الحفظ بقوله ﴿إِنَّهُ يَعْلَمُ الْجَهْرَ وَمَا يَخْفَى﴾؟","answer":"من يعلم ظاهر التلاوة وخفي الصدر قادر على جمع القرآن فيه وصيانة ما استودعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص10–22.","url":""}]},{"id":"s87-7","number":7,"surah":87,"verses":[8],"verseLabel":"الأعلى: 8","question":"ما جمال ﴿وَنُيَسِّرُكَ لِلْيُسْرَى﴾؟","answer":"لم يقل نيسر اليسرى لك فقط، بل نهيئ الرسول نفسه لها؛ فيشمل التيسير طبيعته وطريقه وشريعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص23–27.","url":""}]},{"id":"s87-8","number":8,"surah":87,"verses":[9],"verseLabel":"الأعلى: 9","question":"لماذا قُيد التذكير بـ﴿إِنْ نَفَعَتِ الذِّكْرَى﴾؟","answer":"للتوجيه إلى موضع القبول أو لبيان أن الذكرى نافعة في ذاتها لمن يستجيب؛ لا لإسقاط الدعوة عن المعرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص28–42.","url":""}]},{"id":"s87-9","number":9,"surah":87,"verses":[10,11],"verseLabel":"الأعلى: 10–11","question":"كيف قابل ﴿سَيَذَّكَّرُ مَنْ يَخْشَى﴾ بـ﴿يَتَجَنَّبُهَا الْأَشْقَى﴾؟","answer":"الخشية تقرب صاحبها من الذكرى، والشقاء يدفع صاحبه إلى تجنبها؛ فكأن الموعظة ميزان يكشف باطن المتلقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص28–42.","url":""}]},{"id":"s87-10","number":10,"surah":87,"verses":[12,13],"verseLabel":"الأعلى: 12–13","question":"ما معنى أنه ﴿لَا يَمُوتُ فِيهَا وَلَا يَحْيَى﴾؟","answer":"لا يموت فيستريح ولا يحيا حياة نافعة؛ نُفي عنه طرفا الخلاص في بقاء مؤلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص28–42.","url":""}]},{"id":"s87-11","number":11,"surah":87,"verses":[14,15],"verseLabel":"الأعلى: 14–15","question":"لماذا رُتب ﴿تَزَكَّى وَذَكَرَ اسْمَ رَبِّهِ فَصَلَّى﴾؟","answer":"تطهير القلب يثمر ذكر اللسان، والذكر يثمر عبادة الجوارح؛ فانتظم الباطن والقول والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص43–50.","url":""}]},{"id":"s87-12","number":12,"surah":87,"verses":[16,17],"verseLabel":"الأعلى: 16–17","question":"ما قوة المقابلة بين إيثار الدنيا وخيرية الآخرة وأبقويتها؟","answer":"«تؤثرون» تكشف اختيارًا، ثم يرد الميزان بميزتين: الآخرة خير في نوعها وأبقى في زمنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص51–58.","url":""}]},{"id":"s87-13","number":13,"surah":87,"verses":[18,19],"verseLabel":"الأعلى: 18–19","question":"لماذا ختمت بذكر صحف إبراهيم وموسى؟","answer":"لتقرر أن أصول التزكية والآخرة ليست دعوة طارئة، بل رسالة متصلة في أقدم الصحف.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص59–67.","url":""}]},{"id":"s88-1","number":1,"surah":88,"verses":[1],"verseLabel":"الغاشية: 1","question":"لماذا افتتحت بـ﴿هَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ﴾؟","answer":"سؤال تشويق وتفخيم لخبر يغشى الخلق بهوله، ويستدعي السامع ليرى وجوه الفريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص74–107.","url":""}]},{"id":"s88-2","number":2,"surah":88,"verses":[2,3,4,5,6,7],"verseLabel":"الغاشية: 2–7","question":"لماذا بدأ مشهد القيامة بالوجوه لا بالأجساد؟","answer":"الوجه أسرع صفحة تكشف الذل والتعب والخوف؛ ومنه يمتد الوصف إلى العمل والطعام والشراب.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص74–107.","url":""}]},{"id":"s88-3","number":3,"surah":88,"verses":[3],"verseLabel":"الغاشية: 3","question":"ما المفارقة في ﴿عَامِلَةٌ نَاصِبَةٌ﴾؟","answer":"عملت وتعبت، لكن بلا إيمان أو على عمل باطل؛ فليس كل نصب طريق نجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص74–107.","url":""}]},{"id":"s88-4","number":4,"surah":88,"verses":[4,5,6,7],"verseLabel":"الغاشية: 4–7","question":"كيف اجتمعت النار الحامية والعين الآنية والضريع؟","answer":"جمع العذاب حرارة الإحراق والغليان وطعامًا لا يغذي؛ كل ما يُطلب للراحة ينقلب أذى.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص74–107.","url":""}]},{"id":"s88-5","number":5,"surah":88,"verses":[6,7],"verseLabel":"الغاشية: 6–7","question":"لماذا نُفي عن الضريع أن يسمن أو يغني من جوع؟","answer":"نُفيت وظيفتا الطعام: بناء الجسد وإزالة الألم، فبقي اسمه دون نفعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص74–107.","url":""}]},{"id":"s88-6","number":6,"surah":88,"verses":[8,9,10],"verseLabel":"الغاشية: 8–10","question":"كيف قابلت الوجوه الناعمة بالوجوه الخاشعة؟","answer":"قابلت الذل بالنعومة، والنصب بالرضا عن السعي، والنار بالجنة العالية؛ فظهر أثر الطريق على الوجه والمكان.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص74–134.","url":""}]},{"id":"s88-7","number":7,"surah":88,"verses":[11],"verseLabel":"الغاشية: 11","question":"ما دلالة ﴿لَا تَسْمَعُ فِيهَا لَاغِيَةً﴾؟","answer":"نُفي حتى الصوت العابث المؤذي، فصار صفاء السمع جزءًا من نعيم الجنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص108–134.","url":""}]},{"id":"s88-8","number":8,"surah":88,"verses":[12,13,14,15,16],"verseLabel":"الغاشية: 12–16","question":"لماذا فُصل نعيم الجنة في عين وسرر وأكواب ونمارق وزرابي؟","answer":"انتقل من الشراب إلى الجلوس والخدمة والاتكاء والأرض، فأحاط بالإنسان من كل جهة بحاجاته المادية والنفسية.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص108–134.","url":""}]},{"id":"s88-9","number":9,"surah":88,"verses":[17],"verseLabel":"الغاشية: 17","question":"لماذا بدأ النظر بالإبل؟","answer":"هي أقرب الحيوان إلى خبرة المخاطبين وأجمع للعجب في خلقها ونفعها وصبرها، فبدأ بالحاضر المألوف الذي لم يتأملوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص135–148.","url":""}]},{"id":"s88-10","number":10,"surah":88,"verses":[17,18,19,20],"verseLabel":"الغاشية: 17–20","question":"ما نظام الانتقال من الإبل إلى السماء فالجبال فالأرض؟","answer":"ينقل العين من القريب الحي إلى العلو ثم الشاخص ثم البساط الممتد؛ جولة بصرية كاملة بلا تكلف.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص135–148.","url":""}]},{"id":"s88-11","number":11,"surah":88,"verses":[18,19,20],"verseLabel":"الغاشية: 18–20","question":"لماذا تنوعت الأفعال: خُلقت، رُفعت، نُصبت، سُطحت؟","answer":"اختير لكل مخلوق فعل يجسد هيئته الخاصة، مع بناء الجميع للمجهول لإبراز الصنعة والدلالة على الصانع.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص135–148.","url":""}]},{"id":"s88-12","number":12,"surah":88,"verses":[21,22],"verseLabel":"الغاشية: 21–22","question":"ما الفرق بين ﴿مُذَكِّرٌ﴾ و﴿لَسْتَ عَلَيْهِمْ بِمُصَيْطِرٍ﴾؟","answer":"المذكر يبلغ ويوقظ، أما المسيطر فيكره ويهيمن؛ فحددت مهمة الرسول دون إلغاء الحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص149–165.","url":""}]},{"id":"s88-13","number":13,"surah":88,"verses":[23,24],"verseLabel":"الغاشية: 23–24","question":"كيف نفهم الاستثناء ﴿إِلَّا مَنْ تَوَلَّى وَكَفَرَ﴾؟","answer":"منقطع بمعنى لكن: لست مسيطرًا، لكن من تولى فالله يعذبه؛ لم يُجعل الإكراه وظيفة للرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص149–165.","url":""}]},{"id":"s88-14","number":14,"surah":88,"verses":[25,26],"verseLabel":"الغاشية: 25–26","question":"لماذا ختمت بـ﴿إِنَّ إِلَيْنَا إِيَابَهُمْ ثُمَّ إِنَّ عَلَيْنَا حِسَابَهُمْ﴾؟","answer":"قدم الجارين للاختصاص، وكرر «إن» ليحسم جهتي المصير: الرجوع إلينا والحساب علينا.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص166–174.","url":""}]},{"id":"s89-1","number":1,"surah":89,"verses":[1,2,3,4,5],"verseLabel":"الفجر: 1–5","question":"لماذا أقسم بالفجر والليالي العشر والشفع والوتر والليل؟","answer":"في تعيين الفجر والليالي العشر والشفع والوتر أقوال متعددة؛ ومن أشهرها فجر الصبح أو يوم النحر، وعشر ذي الحجة، والشفع والوتر على العموم أو أيام مخصوصة. ويجمعها تعظيم آيات الزمن والعبادة وانتقال الليل إلى النور تمهيدًا لزوال سلطان الطغاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص182–194.","url":""}]},{"id":"s89-2","number":2,"surah":89,"verses":[5],"verseLabel":"الفجر: 5","question":"ما معنى السؤال ﴿هَلْ فِي ذَلِكَ قَسَمٌ لِذِي حِجْرٍ﴾؟","answer":"الحِجر عقل يمنع صاحبه من السفه؛ والسؤال يقرر أن هذه الآيات تكفي من يحجزه عقله عن التكذيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص195–201.","url":""}]},{"id":"s89-3","number":3,"surah":89,"verses":[6],"verseLabel":"الفجر: 6","question":"لماذا انتقل من القسم إلى ﴿أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ﴾؟","answer":"جعل التاريخ مشهدًا يُرى، وأضاف الرب إلى النبي تثبيتًا بأن ربه الذي أهلك الأولين يرعاه.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص202–235.","url":""}]},{"id":"s89-4","number":4,"surah":89,"verses":[6,7,8,9,10],"verseLabel":"الفجر: 6–10","question":"لماذا جُمعت عاد وثمود وفرعون؟","answer":"نماذج لقوة العمران والصخر والجند؛ تنوعت أدوات السلطان واتحدت عاقبة الطغيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص202–235.","url":""}]},{"id":"s89-5","number":5,"surah":89,"verses":[7],"verseLabel":"الفجر: 7","question":"ما دلالة وصف إرم بـ﴿ذَاتِ الْعِمَادِ﴾؟","answer":"يوحي بقوة البناء أو الأجسام والخيام، فيبرز ما كان يُرى من أسباب المنعة قبل زوالها.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص202–235.","url":""}]},{"id":"s89-6","number":6,"surah":89,"verses":[9],"verseLabel":"الفجر: 9","question":"ما سرّ التعبير بقوله تعالى: إن ثمود ﴿جَابُوا الصَّخْرَ بِالْوَادِ﴾؟","answer":"«جابوا» تشق الصخر وتقطعه، فتجعل صلابة عمرانهم حاضرة ثم تثبت أنها لم تمنع العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص202–235.","url":""}]},{"id":"s89-7","number":7,"surah":89,"verses":[10],"verseLabel":"الفجر: 10","question":"ما دلالة ﴿فِرْعَوْنَ ذِي الْأَوْتَادِ﴾؟","answer":"الأوتاد كناية عن ثبات الملك أو كثرة الجنود وأدوات التعذيب؛ وكلها صورة لسلطان ظنه صاحبه راسخًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص202–235.","url":""}]},{"id":"s89-8","number":8,"surah":89,"verses":[12],"verseLabel":"الفجر: 12","question":"ما سرّ التعبير بقوله تعالى: ﴿فَأَكْثَرُوا فِيهَا الْفَسَادَ﴾ بعد الطغيان؟","answer":"الطغيان تجاوز داخلي للحد، وكثرة الفساد أثره المنتشر في البلاد؛ فانتقل من الأصل إلى النتيجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص202–235.","url":""}]},{"id":"s89-9","number":9,"surah":89,"verses":[13],"verseLabel":"الفجر: 13","question":"ما الصورة في ﴿فَصَبَّ عَلَيْهِمْ رَبُّكَ سَوْطَ عَذَابٍ﴾؟","answer":"جعل العذاب كالسوط المصبوب المتصل؛ يجمع ألم الضرب وشمول السيل وسرعة الأخذ.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص202–235.","url":""}]},{"id":"s89-10","number":10,"surah":89,"verses":[14],"verseLabel":"الفجر: 14","question":"لماذا ختم قصصهم بـ﴿إِنَّ رَبَّكَ لَبِالْمِرْصَادِ﴾؟","answer":"المرصاد موضع ترقب، فيشعر الطاغية أن حركته كلها تحت مراقبة لا يفلت منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص202–235.","url":""}]},{"id":"s89-11","number":11,"surah":89,"verses":[15,16],"verseLabel":"الفجر: 15–16","question":"ما الخطأ في قول الإنسان عند النعمة ﴿رَبِّي أَكْرَمَنِ﴾ وعند التضييق ﴿رَبِّي أَهَانَنِ﴾؟","answer":"جعل سعة المال معيار الكرامة وضيقها معيار الهوان، مع أن الحالتين ابتلاء يكشف العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص236–264.","url":""}]},{"id":"s89-12","number":12,"surah":89,"verses":[17,18,19,20],"verseLabel":"الفجر: 17–20","question":"كيف ردت السورة على هذا الميزان؟","answer":"نقلت القضية من مقدار ما يأخذ الإنسان إلى ما يعطيه: إكرام اليتيم والحض على الطعام وترك أكل التراث وحب المال.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص236–264.","url":""}]},{"id":"s89-13","number":13,"surah":89,"verses":[19],"verseLabel":"الفجر: 19","question":"ما سرّ التعبير بقوله تعالى: ﴿تَأْكُلُونَ التُّرَاثَ أَكْلًا لَمًّا﴾؟","answer":"«لمًّا» تصور جمع المال من كل وجه بلا تمييز حق وضعيف، والمصدر يؤكد شراهة الفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص236–264.","url":""}]},{"id":"s89-14","number":14,"surah":89,"verses":[21],"verseLabel":"الفجر: 21","question":"ما أثر تكرار ﴿دُكَّتِ الْأَرْضُ دَكًّا دَكًّا﴾؟","answer":"المصدر والتكرار يصوران سحقًا متتابعًا يزيل كل ارتفاع، مقابل عمران الطغاة واعتزاز الغني.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص265–288.","url":""}]},{"id":"s89-15","number":15,"surah":89,"verses":[22],"verseLabel":"الفجر: 22","question":"لماذا جاء ﴿وَجَاءَ رَبُّكَ وَالْمَلَكُ صَفًّا صَفًّا﴾؟","answer":"مجيء يليق بجلاله للفصل، واصطفاف الملائكة يحيط المشهد بنظام وهيبة لا مجال فيه للفوضى.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص265–288.","url":""}]},{"id":"s89-16","number":16,"surah":89,"verses":[23,24],"verseLabel":"الفجر: 23–24","question":"ما المفارقة في ﴿يَتَذَكَّرُ الْإِنْسَانُ وَأَنَّى لَهُ الذِّكْرَى﴾؟","answer":"يأتي التذكر بعد فوات زمن العمل، فيصير الوعي نفسه حسرة ويقول: ليتني قدمت لحياتي الحقيقية.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص265–288.","url":""}]},{"id":"s89-17","number":17,"surah":89,"verses":[27,28,29,30],"verseLabel":"الفجر: 27–30","question":"لماذا انتقل الختام إلى خطاب النفس المطمئنة؟","answer":"بعد اضطراب الطغاة وندم الغافل يأتي النداء الشخصي الهادئ؛ رجوع برضا متبادل ودخول بين العباد ثم الجنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص289–301.","url":""}]},{"id":"s90-1","number":1,"surah":90,"verses":[1,2],"verseLabel":"البلد: 1–2","question":"لماذا أقسم بالبلد ثم قال ﴿وَأَنْتَ حِلٌّ بِهَذَا الْبَلَدِ﴾؟","answer":"ازدادت حرمة المكان بحلول النبي فيه، وقد تحمل «حل» معنى الإقامة أو استحلال أذاه؛ فيجتمع التشريف والتعجيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص309–329.","url":""}]},{"id":"s90-2","number":2,"surah":90,"verses":[3],"verseLabel":"البلد: 3","question":"ما سعة قوله ﴿وَوَالِدٍ وَمَا وَلَدَ﴾؟","answer":"يستوعب آدم وذريته أو كل والد وولده، فيقسم بسلسلة الحياة التي يعاني أفرادها الكبد.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص309–329.","url":""}]},{"id":"s90-3","number":3,"surah":90,"verses":[4],"verseLabel":"البلد: 4","question":"ما سرّ التعبير بقوله تعالى: ﴿خَلَقْنَا الْإِنْسَانَ فِي كَبَدٍ﴾ لا «مع كبد»؟","answer":"«في» تصوره محاطًا بالمشقة منذ الولادة إلى الموت، لا تطرأ عليه من خارج حياته فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص309–329.","url":""}]},{"id":"s90-4","number":4,"surah":90,"verses":[5,6,7],"verseLabel":"البلد: 5–7","question":"كيف تكشف الأسئلة غرور صاحب المال؟","answer":"يظن ألا يقدر عليه أحد، ويتباهى بإهلاك المال، ثم ينسى العين التي تراه؛ فتتدرج الأسئلة من القوة إلى الإنفاق إلى المراقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص330–345.","url":""}]},{"id":"s90-5","number":5,"surah":90,"verses":[8,9,10],"verseLabel":"البلد: 8–10","question":"لماذا ذُكرت العينان واللسان والشفتان ثم النجدان؟","answer":"بعد أدوات الإدراك والبيان جاءت هداية الطريقين؛ فالنعمة ليست جسدًا فقط بل قدرة على اختيار الخير والشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص346–354.","url":""}]},{"id":"s90-6","number":6,"surah":90,"verses":[11],"verseLabel":"البلد: 11","question":"ما الصورة في ﴿فَلَا اقْتَحَمَ الْعَقَبَةَ﴾؟","answer":"شُبه طريق الخير بعقبة شاقة لا تعبر بالتمني، و«اقتحم» تصور دخولًا بعزم ومجاهدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص355–384.","url":""}]},{"id":"s90-7","number":7,"surah":90,"verses":[12],"verseLabel":"البلد: 12","question":"لماذا سأل ﴿وَمَا أَدْرَاكَ مَا الْعَقَبَةُ﴾؟","answer":"يفخم حقيقتها ثم يفاجئ بأن تجاوزها ليس بطولة جسدية بل تحرير جائع وإطعام ضعيف.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص355–384.","url":""}]},{"id":"s90-8","number":8,"surah":90,"verses":[13,14,15,16],"verseLabel":"البلد: 13–16","question":"لماذا بدأ بفك الرقبة ثم الإطعام في يوم المسغبة؟","answer":"جمع إزالة قيد دائم ودفع حاجة عاجلة، واختار أقسى ظرف للجوع ليظهر صدق التضحية.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص355–384.","url":""}]},{"id":"s90-9","number":9,"surah":90,"verses":[15,16],"verseLabel":"البلد: 15–16","question":"لماذا خُص اليتيم ذا المقربة والمسكين ذا المتربة؟","answer":"جمع حاجة القرابة التي تستدعي الصلة وحاجة الفقير الذي لصق بالتراب، فبلغ الإحسان القريب والمنقطع.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص355–384.","url":""}]},{"id":"s90-10","number":10,"surah":90,"verses":[17],"verseLabel":"البلد: 17","question":"لماذا جاء الإيمان بعد أعمال الإحسان بـ﴿ثُمَّ كَانَ مِنَ الَّذِينَ آمَنُوا﴾؟","answer":"«ثم» للرتبة: لا تكتمل قيمة العمل بلا أصل الإيمان، ثم لا ينفرد المؤمن بل يدخل جماعة التواصي.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص355–384.","url":""}]},{"id":"s90-11","number":11,"surah":90,"verses":[17],"verseLabel":"البلد: 17","question":"ما سر تكرار ﴿تَوَاصَوْا﴾ مع الصبر والمرحمة؟","answer":"الخير يحتاج تثبيتًا متبادلًا أمام المشقة، ورحمة متبادلة تمنع العمل من الجفاف؛ فالمجتمع يعين الفرد على العقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص355–384.","url":""}]},{"id":"s90-12","number":12,"surah":90,"verses":[18,19,20],"verseLabel":"البلد: 18–20","question":"لماذا سمي الفريقان أصحاب الميمنة والمشأمة؟","answer":"اليمين رمز اليمن والقبول، والشمال رمز الشؤم والرد؛ ثم تختم النار المؤصدة كل منفذ على أصحاب المشأمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص385–402.","url":""}]},{"id":"s90-13","number":13,"surah":90,"verses":[20],"verseLabel":"البلد: 20","question":"ما دلالة ﴿نَارٌ مُؤْصَدَةٌ﴾؟","answer":"مغلقة محكمة الأبواب، فتقابل العقبة المفتوحة للمقتحم بنهاية لا مخرج منها للمعرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص385–402.","url":""}]},{"id":"s91-1","number":1,"surah":91,"verses":[1,2,3,4,5,6,7],"verseLabel":"الشمس: 1–7","question":"لماذا توالت سبعة أقسام قبل الحديث عن النفس؟","answer":"يمهد انتظام الشمس والقمر والنهار والليل والسماء والأرض لفكرة أن النفس كذلك مسواة ذات قانون أخلاقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص411–451.","url":""}]},{"id":"s91-2","number":2,"surah":91,"verses":[1,2],"verseLabel":"الشمس: 1–2","question":"ما المقابلة بين الشمس وضحاها والقمر إذا تلاها؟","answer":"الشمس أصل الضوء الظاهر، والقمر يتبعها ويعكس نورها؛ فجمع الأصل والتابع في حركة كونية.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص411–451.","url":""}]},{"id":"s91-3","number":3,"surah":91,"verses":[3,4],"verseLabel":"الشمس: 3–4","question":"ما سرّ التعبير بقوله تعالى: عن النهار ﴿جَلَّاهَا﴾ وعن الليل ﴿يَغْشَاهَا﴾؟","answer":"النهار يكشف الشمس أو الأرض، والليل يغطيها؛ فالفعلان يرسمان صراع الكشف والستر.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص411–451.","url":""}]},{"id":"s91-4","number":4,"surah":91,"verses":[5,6],"verseLabel":"الشمس: 5–6","question":"ما أثر ﴿وَمَا بَنَاهَا﴾ و﴿وَمَا طَحَاهَا﴾؟","answer":"«ما» تفخم الخالق أو فعله، والبناء والطحْو يجمعان رفع السماء وبسط الأرض في مقابلة هندسية.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص411–451.","url":""}]},{"id":"s91-5","number":5,"surah":91,"verses":[7],"verseLabel":"الشمس: 7","question":"ما سرّ التعبير في قوله ﴿وَنَفْسٍ وَمَا سَوَّاهَا﴾ بالتنكير؟","answer":"لتشمل كل نفس ولتفخم عجيب تركيبها، ثم يربط تسويتها بتمييزها الأخلاقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص411–451.","url":""}]},{"id":"s91-6","number":6,"surah":91,"verses":[8],"verseLabel":"الشمس: 8","question":"كيف نفهم ﴿فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَاهَا﴾؟","answer":"عرّفها طريق الفجور والتقوى ومكّنها من التمييز، لا أنه أجبرها على الفجور؛ ولذلك صح الجزاء بعدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص411–451.","url":""}]},{"id":"s91-7","number":7,"surah":91,"verses":[9,10],"verseLabel":"الشمس: 9–10","question":"ما المقابلة في ﴿قَدْ أَفْلَحَ مَنْ زَكَّاهَا وَقَدْ خَابَ مَنْ دَسَّاهَا﴾؟","answer":"التزكية تنمية وتطهير يرفعان النفس، والتدسية إخفاء لها في الرذيلة؛ فقابل الظهور بالنمو بالدفن والخسار.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص411–451.","url":""}]},{"id":"s91-8","number":8,"surah":91,"verses":[10],"verseLabel":"الشمس: 10","question":"لماذا اختيرت ﴿دَسَّاهَا﴾؟","answer":"أصلها الدس والإخفاء، فكأن المذنب يدفن فطرته تحت طبقات الهوى حتى تصغر بعد أن سواها الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص411–451.","url":""}]},{"id":"s91-9","number":9,"surah":91,"verses":[11,12],"verseLabel":"الشمس: 11–12","question":"ما سرّ التعبير بقوله تعالى: ﴿كَذَّبَتْ ثَمُودُ بِطَغْوَاهَا إِذِ انْبَعَثَ أَشْقَاهَا﴾؟","answer":"جعل الطغيان علة التكذيب، ثم انبعث أشقى القوم منفذًا لإرادة جماعية؛ فالجريمة ليست فعل فرد معزول.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص452–478.","url":""}]},{"id":"s91-10","number":10,"surah":91,"verses":[13],"verseLabel":"الشمس: 13","question":"ما أثر الجمع بين ﴿نَاقَةَ اللَّهِ وَسُقْيَاهَا﴾؟","answer":"إضافة الناقة إلى الله تشريف وتحذير، وذكر حقها في الماء يبين أن العدوان وقع على آية وعلى عدل معلوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص452–478.","url":""}]},{"id":"s91-11","number":11,"surah":91,"verses":[14],"verseLabel":"الشمس: 14","question":"ما سرّ التعبير بقوله تعالى: ﴿فَدَمْدَمَ عَلَيْهِمْ رَبُّهُمْ بِذَنْبِهِمْ فَسَوَّاهَا﴾؟","answer":"الدمدمة إحاطة بالعذاب، وربطها بذنبهم يثبت العدل، والتسوية جعلت العقوبة عامة كما عم الرضا بالجريمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص452–478.","url":""}]},{"id":"s91-12","number":12,"surah":91,"verses":[15],"verseLabel":"الشمس: 15","question":"ما دلالة ﴿وَلَا يَخَافُ عُقْبَاهَا﴾؟","answer":"الله لا يلحقه خوف من تبعة حكمه كما يخاف البشر؛ فسلطانه وعدله مطلقان.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص452–478.","url":""}]},{"id":"s92-1","number":1,"surah":92,"verses":[1,2,3],"verseLabel":"الليل: 1–3","question":"لماذا أقسم بالليل إذا يغشى والنهار إذا تجلى وما خلق الذكر والأنثى؟","answer":"جمع ستر الليل وكشف النهار وازدواج الخلق، تمهيدًا لتقابل السعي والجزاء في فريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص487–504.","url":""}]},{"id":"s92-2","number":2,"surah":92,"verses":[4],"verseLabel":"الليل: 4","question":"ما أثر التوكيد في ﴿إِنَّ سَعْيَكُمْ لَشَتَّى﴾؟","answer":"يحسم أن الأعمال وإن تشابه ظاهرها متباعدة المقاصد والعواقب؛ فالاختلاف يبدأ من السعي.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص487–504.","url":""}]},{"id":"s92-3","number":3,"surah":92,"verses":[5,6,7],"verseLabel":"الليل: 5–7","question":"لماذا رُتبت صفات الناجي: أعطى واتقى وصدق بالحسنى؟","answer":"جمع بذل اليد وتقوى القلب وتصديق الاعتقاد، ثم جاء تيسير اليسرى ثمرة لاختيار متكامل.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص505–518.","url":""}]},{"id":"s92-4","number":4,"surah":92,"verses":[7],"verseLabel":"الليل: 7","question":"كيف نفهم ﴿فَسَنُيَسِّرُهُ لِلْيُسْرَى﴾؟","answer":"من اختار أسباب الخير فتح الله له أبوابه حتى تصير الطاعة أيسر عليه، فالجزاء يشمل الطريق قبل النهاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص505–518.","url":""}]},{"id":"s92-5","number":5,"surah":92,"verses":[8,9,10],"verseLabel":"الليل: 8–10","question":"كيف قابل الفريق الثاني بالألفاظ نفسها؟","answer":"قابل أعطى ببخل، واتقى باستغنى، وصدق بكذب، واليسرى بالعسرى؛ فبُني المشهد على تناظر يكشف الاختيار.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص505–534.","url":""}]},{"id":"s92-6","number":6,"surah":92,"verses":[8],"verseLabel":"الليل: 8","question":"ما سرّ التعبير بـ﴿اسْتَغْنَى﴾ دون «كان غنيًا»؟","answer":"المراد استغناؤه عن امتثال أمر الله ودعوته، ويحتمل استغناءه بشهوات الدنيا عن نعيم الآخرة؛ فالذم في ادعاء الاكتفاء والإعراض، لا في مجرد وجود المال.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص519–534.","url":""}]},{"id":"s92-7","number":7,"surah":92,"verses":[11],"verseLabel":"الليل: 11","question":"ما قوة السؤال ﴿وَمَا يُغْنِي عَنْهُ مَالُهُ إِذَا تَرَدَّى﴾؟","answer":"يبطل نفع ماله عند سقوطه في الهلاك وجهنم؛ فالأصل الذي توهم به الغنى لا يمنع عنه العاقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص519–534.","url":""}]},{"id":"s92-8","number":8,"surah":92,"verses":[12,13],"verseLabel":"الليل: 12–13","question":"لماذا جمع ﴿إِنَّ عَلَيْنَا لَلْهُدَى وَإِنَّ لَنَا لَلْآخِرَةَ وَالْأُولَى﴾؟","answer":"تكفل الله ببيان الطريق وملك النهايتين؛ فلا نقص في الدلالة ولا مهرب إلى ملك آخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص535–541.","url":""}]},{"id":"s92-9","number":9,"surah":92,"verses":[14],"verseLabel":"الليل: 14","question":"ما سرّ التعبير بقوله تعالى ﴿فَأَنْذَرْتُكُمْ نَارًا تَلَظَّى﴾؟","answer":"الفاء تبني الإنذار على تمام الهداية والملك، و«تلظى» تجعل اللهب متقدًا متجددًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص542–550.","url":""}]},{"id":"s92-10","number":10,"surah":92,"verses":[15,16],"verseLabel":"الليل: 15–16","question":"لماذا حُصر صلي النار في ﴿الْأَشْقَى﴾ الذي كذب وتولى؟","answer":"المراد الصلي الكامل الملازم، وأبرز وصفين يجمعان فساد الاعتقاد والعمل: التكذيب والإعراض.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص542–550.","url":""}]},{"id":"s92-11","number":11,"surah":92,"verses":[17,18],"verseLabel":"الليل: 17–18","question":"ما دلالة ﴿الْأَتْقَى الَّذِي يُؤْتِي مَالَهُ يَتَزَكَّى﴾؟","answer":"العطاء عنده وسيلة لتطهير النفس والمال، لا شراء منزلة اجتماعية.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص551–568.","url":""}]},{"id":"s92-12","number":12,"surah":92,"verses":[19,20],"verseLabel":"الليل: 19–20","question":"لماذا نُفيت المكافأة البشرية في ﴿وَمَا لِأَحَدٍ عِنْدَهُ مِنْ نِعْمَةٍ تُجْزَى﴾؟","answer":"ليثبت أن البذل ليس رد دين ولا طلب ثناء، وإنما ابتغاء وجه ربه الأعلى.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص551–568.","url":""}]},{"id":"s92-13","number":13,"surah":92,"verses":[20],"verseLabel":"الليل: 20","question":"ما مناسبة اسم ﴿رَبِّهِ الْأَعْلَى﴾؟","answer":"من ابتغى وجه الأعلى تحرر من نظر الأدنى ومنّته، وقابل استغناء البخيل بتعلقه بربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص551–568.","url":""}]},{"id":"s92-14","number":14,"surah":92,"verses":[21],"verseLabel":"الليل: 21","question":"لماذا ختمت بـ﴿وَلَسَوْفَ يَرْضَى﴾ دون ذكر ما يرضيه؟","answer":"حذف المفعول يطلق الرضا في كل نعيم وكرامة، والتوكيد يعد بوصول محقق إلى غاية الرضوان.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص551–568.","url":""}]},{"id":"s93-1","number":1,"surah":93,"verses":[1,2],"verseLabel":"الضحى: 1–2","question":"ما مناسبة القسم بالضحى والليل إذا سجى لحال النبي؟","answer":"تعاقب النور والسكون يعلّم أن فتور الوحي ليس هجرًا؛ كما لا يعني مجيء الليل زوال النهار.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص576–585.","url":""}]},{"id":"s93-2","number":2,"surah":93,"verses":[2],"verseLabel":"الضحى: 2","question":"لماذا اختير ﴿سَجَى﴾ لليل؟","answer":"يوحي بسكون الظلمة واستقرارها لا بعنفها، فيجعل الليل غطاء هادئًا مناسبًا للتثبيت.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص576–585.","url":""}]},{"id":"s93-3","number":3,"surah":93,"verses":[3],"verseLabel":"الضحى: 3","question":"ما الفرق بين ﴿مَا وَدَّعَكَ رَبُّكَ﴾ و«ما تركك»؟","answer":"التوديع ترك مع مفارقة وشعور، فنفاه ليزيل ألم الانقطاع، ثم نفى البغض بـ«وما قلى» دون إعادة الضمير مراعاة ولطفًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص576–585.","url":""}]},{"id":"s93-4","number":4,"surah":93,"verses":[3],"verseLabel":"الضحى: 3","question":"لماذا حُذف مفعول ﴿قَلَى﴾؟","answer":"لئلا يُواجه النبي حتى بلفظ «قلاك» في مقام النفي، ولأن المفعول معلوم؛ فالحذف ألطف وأوجز ويحفظ الفاصلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص576–585.","url":""}]},{"id":"s93-5","number":5,"surah":93,"verses":[4],"verseLabel":"الضحى: 4","question":"ما سرّ التعبير بقوله تعالى ﴿وَلَلْآخِرَةُ خَيْرٌ لَكَ مِنَ الْأُولَى﴾؟","answer":"لا يقتصر الوعد على الآخرة الدار، بل يشمل أن كل حال لاحقة من الرسالة ستكون خيرًا من السابقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص586–594.","url":""}]},{"id":"s93-6","number":6,"surah":93,"verses":[5],"verseLabel":"الضحى: 5","question":"ما أثر ﴿وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضَى﴾؟","answer":"تراكم اللام وسوف يمد الوعد، وإضافة الرب إلى النبي تربط العطاء بالرعاية حتى يبلغ الرضا.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص586–594.","url":""}]},{"id":"s93-7","number":7,"surah":93,"verses":[6,7,8],"verseLabel":"الضحى: 6–8","question":"لماذا ذُكرت ثلاث نعم: اليتم والضلال والعيلة؟","answer":"قوبلت بثلاث رعايات: الإيواء والهداية والإغناء، لتكون خبرة الماضي دليلًا على أن الرب لم يتركه.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص595–603.","url":""}]},{"id":"s93-8","number":8,"surah":93,"verses":[7],"verseLabel":"الضحى: 7","question":"كيف نفهم ﴿وَوَجَدَكَ ضَالًّا فَهَدَى﴾؟","answer":"أي وجدك حائرًا أو غافلًا عما يراد منك من أمر النبوة وتفاصيل الشرائع، فهداك إلى النبوة والرسالة؛ وليس المراد ضلال الشرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص595–603.","url":""}]},{"id":"s93-9","number":9,"surah":93,"verses":[8],"verseLabel":"الضحى: 8","question":"ما سرّ التعبير بقوله تعالى ﴿عَائِلًا فَأَغْنَى﴾؟","answer":"العائل المحتاج، والإغناء يشمل غنى الكفاية والقلب بما ساق الله إليه، لا مجرد كثرة المال.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص595–603.","url":""}]},{"id":"s93-10","number":10,"surah":93,"verses":[9,10,11],"verseLabel":"الضحى: 9–11","question":"كيف قابلت الأوامر النعم الثلاث؟","answer":"كما آواك فلا تقهر اليتيم، وهداك فلا تزجر السائل، وأغناك فحدث بالنعمة؛ شكر عملي من جنس العطاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص604–613.","url":""}]},{"id":"s93-11","number":11,"surah":93,"verses":[9],"verseLabel":"الضحى: 9","question":"لماذا اختير ﴿فَلَا تَقْهَرْ﴾ مع اليتيم؟","answer":"القهر غلبة مع إذلال، وهو أشد ما يشعر به من فقد الحامي؛ فنهي عن كسر القلب لا عن أخذ المال فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص604–613.","url":""}]},{"id":"s93-12","number":12,"surah":93,"verses":[10],"verseLabel":"الضحى: 10","question":"من يشمله ﴿السَّائِلَ فَلَا تَنْهَرْ﴾؟","answer":"يشمل سائل المال وسائل العلم؛ وكلاهما محتاج إلى جواب لا يجرح كرامته.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص604–613.","url":""}]},{"id":"s93-13","number":13,"surah":93,"verses":[11],"verseLabel":"الضحى: 11","question":"كيف يكون التحديث بالنعمة شكرًا لا مباهاة؟","answer":"إذا نسبها إلى المنعم وقصد الترغيب والثناء عليه؛ أما نسبتها للنفس والتعالي بها فيناقض السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص604–613.","url":""}]},{"id":"s94-1","number":1,"surah":94,"verses":[1],"verseLabel":"الشرح: 1","question":"لماذا افتتحت بـ﴿أَلَمْ نَشْرَحْ لَكَ صَدْرَكَ﴾؟","answer":"استفهام تقرير يذكّر بنعمة باطنة يعرف أثرها، ويصل السورة بوعد الضحى ورعاية الرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص619–631.","url":""}]},{"id":"s94-2","number":2,"surah":94,"verses":[1],"verseLabel":"الشرح: 1","question":"ما دلالة تقديم ﴿لَكَ﴾؟","answer":"يبرز اختصاص النبي بالعناية ويجعل الشرح هبة موجهة إليه قبل ذكر محلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص619–631.","url":""}]},{"id":"s94-3","number":3,"surah":94,"verses":[2,3],"verseLabel":"الشرح: 2–3","question":"ما الصورة في ﴿وَوَضَعْنَا عَنْكَ وِزْرَكَ الَّذِي أَنْقَضَ ظَهْرَكَ﴾؟","answer":"شُبه الثقل المعنوي بحمل يسمع له الظهر نقيضًا، ثم جاء الوضع راحة محسوسة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص619–631.","url":""}]},{"id":"s94-4","number":4,"surah":94,"verses":[4],"verseLabel":"الشرح: 4","question":"كيف رُفع ذكر النبي؟","answer":"قرن الله اسمه باسمه في الشهادة والأذان والطاعة والصلاة عليه، فصار ذكره ممتدًا مع الرسالة لا بالسلطان.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص619–631.","url":""}]},{"id":"s94-5","number":5,"surah":94,"verses":[5,6],"verseLabel":"الشرح: 5–6","question":"لماذا تكرر ﴿فَإِنَّ مَعَ الْعُسْرِ يُسْرًا﴾؟","answer":"التكرار تثبيت بعد ذكر الأثقال، وتعريف العسر وتنكير اليسر يشعر بأن العسر واحد تحيط به وجوه من اليسر.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص632–637.","url":""}]},{"id":"s94-6","number":6,"surah":94,"verses":[5,6],"verseLabel":"الشرح: 5–6","question":"ما سرّ التعبير بـ﴿مَعَ الْعُسْرِ﴾ دون «بعد العسر»؟","answer":"ليقرر أن بذور التيسير تصاحب الشدة نفسها، وإن ظهر تمامها بعدها؛ فالمعية أسرع طمأنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص632–637.","url":""}]},{"id":"s94-7","number":7,"surah":94,"verses":[7],"verseLabel":"الشرح: 7","question":"ما سرّ التعبير بقوله تعالى ﴿فَإِذَا فَرَغْتَ فَانْصَبْ﴾ دون تحديد العمل؟","answer":"ليعم كل فراغ من شأن نافع: لا تجعل انتهاء مهمة فراغًا سلبيًا، بل انتقل إلى عبادة وجهد آخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص638–645.","url":""}]},{"id":"s94-8","number":8,"surah":94,"verses":[8],"verseLabel":"الشرح: 8","question":"ما دلالة ﴿وَإِلَى رَبِّكَ فَارْغَبْ﴾ بتقديم الجار؟","answer":"يقصر الرغبة القلبية العليا على الله، حتى لا يتحول النصب إلى طلب ثناء الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص638–645.","url":""}]},{"id":"s94-9","number":9,"surah":94,"verses":[7,8],"verseLabel":"الشرح: 7–8","question":"كيف يخدم الختام معنى السورة؟","answer":"بعد شرح الصدر ووضع الحمل يأتي قانون الحركة: اعمل ثم وجّه رغبتك؛ فالراحة ليست توقفًا بل قوة لرسالة جديدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص638–645.","url":""}]},{"id":"s95-1","number":1,"surah":95,"verses":[1,2,3],"verseLabel":"التين: 1–3","question":"لماذا أقسم بالتين والزيتون وطور سينين والبلد الأمين؟","answer":"يجمع مواضع أو رموز رسالات كبرى وبركات الغذاء والوحي، ثم يصلها بالإنسان المكلّف.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص651–701.","url":""}]},{"id":"s95-2","number":2,"surah":95,"verses":[2],"verseLabel":"التين: 2","question":"ما دلالة ﴿طُورِ سِينِينَ﴾؟","answer":"الطور جبل الوحي لموسى، فانتقل القسم من أرض البركة إلى مشهد التكليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص651–701.","url":""}]},{"id":"s95-3","number":3,"surah":95,"verses":[3],"verseLabel":"التين: 3","question":"لماذا وُصف البلد بـ﴿الْأَمِينِ﴾؟","answer":"أسند الأمن إلى المكان للمبالغة، وهو مكة التي يأمن فيها الناس ويحفظ فيها الوحي الخاتم.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص651–701.","url":""}]},{"id":"s95-4","number":4,"surah":95,"verses":[4],"verseLabel":"التين: 4","question":"ما معنى ﴿فِي أَحْسَنِ تَقْوِيمٍ﴾؟","answer":"في أحسن اعتدال جسدي وعقلي وفطري يؤهله لمعرفة الحق وحمل التكليف، لا مجرد جمال الصورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص651–701.","url":""}]},{"id":"s95-5","number":5,"surah":95,"verses":[5],"verseLabel":"التين: 5","question":"ما سرّ التعبير بقوله تعالى ﴿ثُمَّ رَدَدْنَاهُ أَسْفَلَ سَافِلِينَ﴾؟","answer":"«ثم» تفيد انقلابًا بعيدًا بعد التكريم؛ فمن عطّل فطرته هبط إلى أرذل العمر أو دركات النار.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص651–701.","url":""}]},{"id":"s95-6","number":6,"surah":95,"verses":[6],"verseLabel":"التين: 6","question":"لماذا جاء ﴿فَلَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ﴾ بالفاء؟","answer":"لأن الجزاء متسبب عن الإيمان والعمل المذكورين في الشرط المعنوي؛ بخلاف سياق الانشقاق المنقطع عن المكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص651–701؛ وج66، ص629–650 (طرف الانشقاق 25).","url":""}]},{"id":"s95-7","number":7,"surah":95,"verses":[6],"verseLabel":"التين: 6","question":"ما دلالة ﴿غَيْرُ مَمْنُونٍ﴾؟","answer":"يحتمل أجرًا غير مقطوع، ويحتمل أجرًا لا يُمنّ به عليهم؛ وحذف المتعلّق يبقي المعنيين ويجمع تمام الأجر واستمراره.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص651–701.","url":""}]},{"id":"s95-8","number":8,"surah":95,"verses":[7],"verseLabel":"التين: 7","question":"إلى من يتجه سؤال ﴿فَمَا يُكَذِّبُكَ بَعْدُ بِالدِّينِ﴾؟","answer":"يواجه الإنسان: أي شيء يحملك بعد دلائل الخلق والتقويم والانقلاب على تكذيب الجزاء؟","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص651–701.","url":""}]},{"id":"s95-9","number":9,"surah":95,"verses":[8],"verseLabel":"التين: 8","question":"لماذا ختمت بـ﴿أَلَيْسَ اللَّهُ بِأَحْكَمِ الْحَاكِمِينَ﴾؟","answer":"كمال الحكمة يقتضي ألا يسوي بين من حفظ التقويم ومن أفسده، فيصبح العدل برهانًا على الدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص651–701.","url":""}]},{"id":"s96-1","number":1,"surah":96,"verses":[1],"verseLabel":"العلق: 1","question":"لماذا كان أول الأمر ﴿اقْرَأْ بِاسْمِ رَبِّكَ﴾؟","answer":"أسس المعرفة على الصلة بالرب؛ فالقراءة ليست استقلال العقل عن الخالق بل استعماله في هدايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص708–735.","url":""}]},{"id":"s96-2","number":2,"surah":96,"verses":[1],"verseLabel":"العلق: 1","question":"ما دلالة إضافة الرب إلى النبي في ﴿رَبِّكَ الَّذِي خَلَقَ﴾؟","answer":"تجمع الرعاية والتعليم والخلق، فتطمئن المتلقي في أول مواجهة للوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص708–735.","url":""}]},{"id":"s96-3","number":3,"surah":96,"verses":[1,2],"verseLabel":"العلق: 1–2","question":"لماذا بدأ الخلق مطلقًا ثم خُص الإنسان من علق؟","answer":"أثبت القدرة العامة أولًا، ثم رد الإنسان المتعلم إلى بداية ضعيفة لئلا يطغى بعلمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص708–735.","url":""}]},{"id":"s96-4","number":4,"surah":96,"verses":[2],"verseLabel":"العلق: 2","question":"ما دلالة التعبير بـ﴿عَلَقٍ﴾؟","answer":"«عَلَق» جمع علقة، وهي القطعة من الدم الجامد المتعلّقة؛ وردُّ الإنسان إلى هذا الأصل الضعيف يقابل ما أُعطيه بعد ذلك من تقويم وعلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص708–735.","url":""}]},{"id":"s96-5","number":5,"surah":96,"verses":[3],"verseLabel":"العلق: 3","question":"لماذا تكرر ﴿اقْرَأْ﴾ ثم قيل ﴿وَرَبُّكَ الْأَكْرَمُ﴾؟","answer":"الأمر الثاني يثبت الاستمرار، واسم الأكرم يزيل رهبة العجز: الرب يتفضل بالعلم فوق ما يتوقع الإنسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص708–735.","url":""}]},{"id":"s96-6","number":6,"surah":96,"verses":[4,5],"verseLabel":"العلق: 4–5","question":"لماذا خُص القلم بالذكر؟","answer":"هو أداة حفظ العلم وتجاوزه زمن المتعلم ومكانه؛ فجمع الوحي بين القراءة الشفوية والذاكرة المكتوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص708–735.","url":""}]},{"id":"s96-7","number":7,"surah":96,"verses":[5],"verseLabel":"العلق: 5","question":"ما سعة ﴿عَلَّمَ الْإِنْسَانَ مَا لَمْ يَعْلَمْ﴾؟","answer":"حذف نوع العلم ليعم كل ما أخرجه الله به من الجهل، ويمنع العالم من نسبة المعرفة إلى ذاته.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص708–735.","url":""}]},{"id":"s96-8","number":8,"surah":96,"verses":[6,7],"verseLabel":"العلق: 6–7","question":"ما العلاقة بين العلم والطغيان في ﴿كَلَّا إِنَّ الْإِنْسَانَ لَيَطْغَى أَنْ رَآهُ اسْتَغْنَى﴾؟","answer":"بعد نعمة التعليم جاء التحذير: قد يقلب الإنسان أدوات المعرفة إلى وهم الاكتفاء، فيتجاوز الحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص736–749.","url":""}]},{"id":"s96-9","number":9,"surah":96,"verses":[7],"verseLabel":"العلق: 7","question":"ما سرّ التعبير بقوله تعالى ﴿رَآهُ اسْتَغْنَى﴾؟","answer":"المشكلة في رؤية النفس لنفسها مكتفية، لا في غنى حقيقي؛ فالضميران يكشفان دائرة الوهم الذاتي.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص736–749.","url":""}]},{"id":"s96-10","number":10,"surah":96,"verses":[8],"verseLabel":"العلق: 8","question":"ما أثر ﴿إِنَّ إِلَى رَبِّكَ الرُّجْعَى﴾؟","answer":"تقديم الجار يقصر المصير عليه، فيكسر وهم الاستغناء بأقصر حجة: ستعود إلى من رباك.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص736–749.","url":""}]},{"id":"s96-11","number":11,"surah":96,"verses":[9,10],"verseLabel":"العلق: 9–10","question":"لماذا صيغ التعجب ﴿أَرَأَيْتَ الَّذِي يَنْهَى عَبْدًا إِذَا صَلَّى﴾؟","answer":"يجعل منع العبادة مشهدًا مستنكرًا بذاته؛ عبد يتصل بربه وطاغية يعترض الطريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص750–773.","url":""}]},{"id":"s96-12","number":12,"surah":96,"verses":[11,12,13,14],"verseLabel":"العلق: 11–14","question":"كيف تحاصر الأسئلة الناهي؟","answer":"تفترض هداية المصلي وتقواه، ثم تكذيب الناهي وتوليه، وتنتهي بسؤال الرؤية الإلهية؛ فلا يبقى له موضع دفاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص750–773.","url":""}]},{"id":"s96-13","number":13,"surah":96,"verses":[15,16],"verseLabel":"العلق: 15–16","question":"ما دلالة ﴿لَنَسْفَعًا بِالنَّاصِيَةِ نَاصِيَةٍ كَاذِبَةٍ خَاطِئَةٍ﴾؟","answer":"السفع أخذ بعنف من مقدم الرأس موضع الكبرياء، ونُسب الكذب والخطأ إلى الناصية ليصبح الجسد شاهدًا على صاحبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص774–808.","url":""}]},{"id":"s96-14","number":14,"surah":96,"verses":[17,18],"verseLabel":"العلق: 17–18","question":"لماذا قابل ﴿نَادِيَهُ﴾ بـ﴿سَنَدْعُ الزَّبَانِيَةَ﴾؟","answer":"تحداه بجماعته ومجلس قوته، ثم قابلهم بملائكة غلاظ؛ فسقط توازن القوى الذي يتوهمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص774–808.","url":""}]},{"id":"s96-15","number":15,"surah":96,"verses":[19],"verseLabel":"العلق: 19","question":"لماذا ختمت بـ﴿لَا تُطِعْهُ وَاسْجُدْ وَاقْتَرِبْ﴾؟","answer":"قابل نهي الطاغية بنهي عن طاعته، ثم جعل السجود الذي أراد منعه عين طريق القرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج67، ص774–808.","url":""}]},{"id":"s97-1","number":1,"surah":97,"verses":[1],"verseLabel":"القدر: 1","question":"لماذا عُظّم نزول القرآن بضمير الغائب ﴿أَنْزَلْنَاهُ﴾ قبل التصريح باسمه؟","answer":"حضوره في الذهن وعلو شأنه يغنيان عن الاسم، وضمير الجمع يعبر عن جلال المنزل لا تعدد الفاعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص15–29.","url":""}]},{"id":"s97-2","number":2,"surah":97,"verses":[1],"verseLabel":"القدر: 1","question":"ما سرّ التعبير بقوله تعالى ﴿فِي لَيْلَةِ الْقَدْرِ﴾ ووقوع ابتداء الإنزال ليلًا؟","answer":"نصّ على أن ابتداء الإنزال كان في الليل؛ لما فيه من هدوء ورهبة واستغفار وتضرع وخشوع، ولقلة الشواغل فيه عن القراءة والتدبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص15–29.","url":""}]},{"id":"s97-3","number":3,"surah":97,"verses":[1],"verseLabel":"القدر: 1","question":"ما دلالات اسم ﴿لَيْلَةِ الْقَدْرِ﴾؟","answer":"يجمع الشرف العظيم والتقدير الذي تنزل به المقادير والتضييق لكثرة الملائكة؛ وأصل المعاني يرفع شأن الليلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص15–29.","url":""}]},{"id":"s97-4","number":4,"surah":97,"verses":[4,38],"verseLabel":"القدر: 4، النبأ 38","question":"ما سرّ تقديم الملائكة على الروح هنا، وتقديم الروح على الملائكة في ﴿يَوْمَ يَقُومُ الرُّوحُ وَالْمَلَائِكَةُ صَفًّا﴾؟","answer":"هنا مقام تنزّل جموع الملائكة فبدأ بالعام ثم خُص الروح تشريفًا، وفي النبأ مقام الوقوف والهيبة فبدأ بأعظمهم وأبرزهم ثم عمّ الملائكة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص30–48؛ وج65، ص700–723 (طرف النبأ 38).","url":""}]},{"id":"s97-5","number":5,"surah":97,"verses":[2],"verseLabel":"القدر: 2","question":"لماذا جاء ﴿وَمَا أَدْرَاكَ مَا لَيْلَةُ الْقَدْرِ﴾؟","answer":"يفخم قدرها قبل بيان فضلها، ويقرر أن عظمتها لا تعرف بقياس البشر وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص15–29.","url":""}]},{"id":"s97-6","number":6,"surah":97,"verses":[3],"verseLabel":"القدر: 3","question":"ما سرّ التعبير بـ﴿خَيْرٌ مِنْ أَلْفِ شَهْرٍ﴾ دون مجرد المساواة؟","answer":"«خير» تفتح باب زيادة لا يحدها رقم المساواة، والألف يمثل زمنًا طويلًا فوق عمر الفرد المعتاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص15–29.","url":""}]},{"id":"s97-7","number":7,"surah":97,"verses":[4],"verseLabel":"القدر: 4","question":"ما أثر ﴿تَنَزَّلُ الْمَلَائِكَةُ وَالرُّوحُ فِيهَا﴾؟","answer":"صيغة التنزل تشعر بالتتابع والكثرة، وإفراد الروح بعد الملائكة تشريف لجبريل.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص30–48.","url":""}]},{"id":"s97-8","number":8,"surah":97,"verses":[4],"verseLabel":"القدر: 4","question":"ما سرّ التعبير بـ﴿مِنْ كُلِّ أَمْرٍ﴾؟","answer":"تفيد مصاحبة ما أذن الله به من المقادير والخير أو لأجل كل أمر حكيم؛ فتتصل الليلة بتدبير السماء للأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص30–48.","url":""}]},{"id":"s97-9","number":9,"surah":97,"verses":[5],"verseLabel":"القدر: 5","question":"ما سرّ تقديم ﴿سَلَامٌ﴾ في قوله تعالى ﴿سَلَامٌ هِيَ﴾؟","answer":"تقديم السلام يجعله خبر الليلة الغالب، فكأنها سلام خالص ممتد لا مجرد وقت يقع فيه السلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص30–48.","url":""}]},{"id":"s97-10","number":10,"surah":97,"verses":[5],"verseLabel":"القدر: 5","question":"ما دلالة ﴿حَتَّى مَطْلَعِ الْفَجْرِ﴾؟","answer":"ترسم حد النعمة الزمني من أول الليل إلى انبثاق النور، فتحيط الليلة كلها بالسلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص30–48.","url":""}]},{"id":"s98-1","number":1,"surah":98,"verses":[1],"verseLabel":"البينة: 1","question":"لماذا جمع ﴿الَّذِينَ كَفَرُوا مِنْ أَهْلِ الْكِتَابِ وَالْمُشْرِكِينَ﴾؟","answer":"جمع فريقين اختلفت معارفهما واتحد موقفهما من الرسول، ليكون مجيء البينة حجة على الجميع.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص54–79.","url":""}]},{"id":"s98-2","number":2,"surah":98,"verses":[1],"verseLabel":"البينة: 1","question":"ما معنى ﴿مُنْفَكِّينَ حَتَّى تَأْتِيَهُمُ الْبَيِّنَةُ﴾؟","answer":"نفى انفكاكهم عن الكفر والضلال إلى مجيء البينة التي طلبوها؛ وشُبّه الإقلاع عن الكفر بالانفكاك لشدة ارتباطهم به.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص54–79.","url":""}]},{"id":"s98-3","number":3,"surah":98,"verses":[2,3],"verseLabel":"البينة: 2–3","question":"لماذا فسرت البينة بـ﴿رَسُولٌ مِنَ اللَّهِ يَتْلُو صُحُفًا مُطَهَّرَةً﴾؟","answer":"بيّن البينة المبهمة بأنها رسول من الله يتلو وحيًا في صحف مطهرة، وفيها أحكام مستقيمة؛ فاجتمع حامل الوحي وتلاوته ومضمونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص54–79.","url":""}]},{"id":"s98-4","number":4,"surah":98,"verses":[2],"verseLabel":"البينة: 2","question":"ما دلالة ﴿صُحُفًا مُطَهَّرَةً﴾؟","answer":"منزهة من الباطل والتحريف، فطهارة الوعاء دليل على طهارة ما يحمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص54–79.","url":""}]},{"id":"s98-5","number":5,"surah":98,"verses":[3],"verseLabel":"البينة: 3","question":"ما سرّ التعبير بقوله تعالى ﴿فِيهَا كُتُبٌ قَيِّمَةٌ﴾؟","answer":"الكتب هنا أحكام مكتوبة مستقيمة تقيم مصالح الناس؛ فالجمع لتعدد ما اشتملت عليه الصحف من شرائع وحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص54–79.","url":""}]},{"id":"s98-6","number":6,"surah":98,"verses":[4],"verseLabel":"البينة: 4","question":"ما المفارقة في أنهم لم يتفرقوا إلا ﴿مِنْ بَعْدِ مَا جَاءَتْهُمُ الْبَيِّنَةُ﴾؟","answer":"الحجة التي كان ينبغي أن تجمعهم كشفت أهواءهم، فصار التفرق بعد العلم أشد إدانة من الجهل السابق.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص80–105.","url":""}]},{"id":"s98-7","number":7,"surah":98,"verses":[5],"verseLabel":"البينة: 5","question":"لماذا لُخص الدين في الإخلاص والصلاة والزكاة؟","answer":"جمع عمل القلب وعبادة البدن وحق المال، ثم سماه دين القيمة لأنه يقيم علاقة الإنسان بربه والناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص80–105.","url":""}]},{"id":"s98-8","number":8,"surah":98,"verses":[6,7,8],"verseLabel":"البينة: 6–8","question":"كيف بُنيت المقابلة بين شر البرية وخير البرية؟","answer":"قابل الكفر بالإيمان والعمل، ونار الخلود بجنات الخلود، ثم أضاف للفائزين رضا متبادلًا وخشية سابقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص106–144.","url":""}]},{"id":"s98-9","number":9,"surah":98,"verses":[7],"verseLabel":"البينة: 7","question":"ما سرّ التعبير بقوله تعالى ﴿أُولَئِكَ هُمْ خَيْرُ الْبَرِيَّةِ﴾ بضمير الفصل؟","answer":"يقصر خير الخلق على من جمع الإيمان والعمل الصالح، لا على النسب أو الدعوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص106–144.","url":""}]},{"id":"s98-10","number":10,"surah":98,"verses":[8],"verseLabel":"البينة: 8","question":"ما جمال ﴿رَضِيَ اللَّهُ عَنْهُمْ وَرَضُوا عَنْهُ﴾؟","answer":"بدأ بالرضا الإلهي لأنه أصل النعمة، ثم رضي العباد بما منحهم؛ فعاد الشعور من المنعم إلى المنعَم عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص106–144.","url":""}]},{"id":"s98-11","number":11,"surah":98,"verses":[8],"verseLabel":"البينة: 8","question":"لماذا ختمت بـ﴿ذَلِكَ لِمَنْ خَشِيَ رَبَّهُ﴾؟","answer":"ردت الأعمال والجزاء إلى قلب يعرف مقام الرب، فالخشية أصل الإخلاص والثبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص106–144.","url":""}]},{"id":"s99-1","number":1,"surah":99,"verses":[1],"verseLabel":"الزلزلة: 1","question":"ما سرّ التعبير بـ﴿إِذَا زُلْزِلَتِ الْأَرْضُ زِلْزَالَهَا﴾ وإضافة الزلزال إليها؟","answer":"أي زلزالها المقدر الذي لا يشبه ما عرفته، والمصدر يؤكد حركة تبلغ غايتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص151–169.","url":""}]},{"id":"s99-2","number":2,"surah":99,"verses":[2],"verseLabel":"الزلزلة: 2","question":"ما الصورة في ﴿وَأَخْرَجَتِ الْأَرْضُ أَثْقَالَهَا﴾؟","answer":"شبه ما في جوفها من موتى وكنوز بأحمال ثقيلة تلقيها حتى تفرغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص151–169.","url":""}]},{"id":"s99-3","number":3,"surah":99,"verses":[3],"verseLabel":"الزلزلة: 3","question":"ما سرّ التعبير في قول الإنسان ﴿مَا لَهَا﴾؟","answer":"سؤال قصير مضطرب يحاكي دهشته أمام أرض مألوفة خرجت عن كل ما يعرفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص151–169.","url":""}]},{"id":"s99-4","number":4,"surah":99,"verses":[4,5],"verseLabel":"الزلزلة: 4–5","question":"كيف تحدّث الأرض أخبارها؟","answer":"تشهد بما عمل عليها، بإذن ربها ووحيه؛ فالمكان الصامت يتحول سجلًا ناطقًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص170–183.","url":""}]},{"id":"s99-5","number":5,"surah":99,"verses":[6],"verseLabel":"الزلزلة: 6","question":"ما دلالة ﴿يَصْدُرُ النَّاسُ أَشْتَاتًا﴾؟","answer":"يرجعون من الموقف جماعات متفرقة بحسب أعمالهم ومصائرهم، بعد أن جمعهم البعث في صعيد واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص184–194.","url":""}]},{"id":"s99-6","number":6,"surah":99,"verses":[6],"verseLabel":"الزلزلة: 6","question":"ما سرّ التعبير بقوله تعالى ﴿لِيُرَوْا أَعْمَالَهُمْ﴾؟","answer":"جعل العمل نفسه معروضًا أو جزاءه مرئيًا، فلا يبقى الحساب رقمًا مجردًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص184–194.","url":""}]},{"id":"s99-7","number":7,"surah":99,"verses":[7,8],"verseLabel":"الزلزلة: 7–8","question":"لماذا تكرر تركيب مثقال الذرة في الخير والشر؟","answer":"التوازي يحسم عدل الميزان من الجهتين، ويمنع احتقار أصغر إحسان أو استهانة بأصغر إساءة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص195–205.","url":""}]},{"id":"s99-8","number":8,"surah":99,"verses":[7,8],"verseLabel":"الزلزلة: 7–8","question":"ما دلالة اختيار ﴿يَرَهُ﴾ لا «يحاسب عليه»؟","answer":"الرؤية أشد حضورًا؛ يقابل الإنسان أثر فعله مواجهة لا يستطيع إنكارها.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص195–205.","url":""}]},{"id":"s100-1","number":1,"surah":100,"verses":[1,2,3,4,5],"verseLabel":"العاديات: 1–5","question":"لماذا افتتحت بخيل تعدو وتقدح وتغير وتثير وتتوسط؟","answer":"تتابع الأفعال يرسم لقطة حية متسارعة بالصوت والشرر والغبار والاقتحام، تمهيدًا لمقابلة وفائها بجحود الإنسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص211–258.","url":""}]},{"id":"s100-2","number":2,"surah":100,"verses":[1],"verseLabel":"العاديات: 1","question":"ما دلالة ﴿ضَبْحًا﴾؟","answer":"صوت أنفاس الخيل عند شدة العدو، فيدخل السامع المشهد من أذنه قبل أن يرى الشرر والغبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص211–238.","url":""}]},{"id":"s100-3","number":3,"surah":100,"verses":[2],"verseLabel":"العاديات: 2","question":"ما سرّ التعبير بقوله تعالى ﴿فَالْمُورِيَاتِ قَدْحًا﴾؟","answer":"حوافرها تقدح الشرر من الصخر، فالفاء تنقل سريعًا من الجري إلى أثره الناري.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص211–238.","url":""}]},{"id":"s100-4","number":4,"surah":100,"verses":[3],"verseLabel":"العاديات: 3","question":"ما مناسبة الإغارة ﴿صُبْحًا﴾؟","answer":"تحديد الإغارة بالصبح يستحضر زمن المباغتة والمفاجأة، ويُظهر أن الإغارة من شأن هذه الخيل المسخّرة للجهاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص211–238.","url":""}]},{"id":"s100-5","number":5,"surah":100,"verses":[4,5],"verseLabel":"العاديات: 4–5","question":"كيف تتحول الحركة إلى صورة مرئية؟","answer":"يثور النقع ثم تدخل الخيل وسط الجمع؛ فانتقل المشهد من أثر مبهم إلى اقتحام مركز الخصم.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص211–238.","url":""}]},{"id":"s100-6","number":6,"surah":100,"verses":[6],"verseLabel":"العاديات: 6","question":"لماذا جاء الجواب ﴿إِنَّ الْإِنْسَانَ لِرَبِّهِ لَكَنُودٌ﴾؟","answer":"قوبل وفاء الحيوان في اندفاعه بأمر صاحبه بجحود الإنسان لربه، وجمعت التوكيدات رسوخ الصفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص239–258.","url":""}]},{"id":"s100-7","number":7,"surah":100,"verses":[7],"verseLabel":"العاديات: 7","question":"من الشهيد في ﴿وَإِنَّهُ عَلَى ذَلِكَ لَشَهِيدٌ﴾؟","answer":"يحتمل الإنسان شاهدًا على نفسه أو الله شاهدًا عليه؛ وكلاهما يغلق باب الإنكار.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص239–258.","url":""}]},{"id":"s100-8","number":8,"surah":100,"verses":[8],"verseLabel":"العاديات: 8","question":"ما سرّ التعبير بقوله تعالى ﴿لِحُبِّ الْخَيْرِ لَشَدِيدٌ﴾ والمراد بالخير المال؟","answer":"سمى المال خيرًا باعتبار ما يراه الناس فيه، ثم كشف شدة التعلق به التي تحوله عن الشكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص239–258.","url":""}]},{"id":"s100-9","number":9,"surah":100,"verses":[9,10],"verseLabel":"العاديات: 9–10","question":"ما التدرج في بعثرة القبور وتحصيل الصدور؟","answer":"يُخرج خفي الأجساد من الأرض ثم خفي النيات من القلوب؛ فلا يبقى سر خارجي ولا داخلي.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص259–282.","url":""}]},{"id":"s100-10","number":10,"surah":100,"verses":[11],"verseLabel":"العاديات: 11","question":"لماذا خُتمت بـ﴿إِنَّ رَبَّهُمْ بِهِمْ يَوْمَئِذٍ لَخَبِيرٌ﴾؟","answer":"علمه قديم دائم، لكن ذكر اليوم يبرز ظهور أثر الخبرة في الحكم والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص259–282.","url":""}]},{"id":"s101-1","number":1,"surah":101,"verses":[1,2,3],"verseLabel":"القارعة: 1–3","question":"لماذا تكرر ﴿الْقَارِعَةُ﴾ ثم قيل ﴿وَمَا أَدْرَاكَ مَا الْقَارِعَةُ﴾؟","answer":"الاسم نفسه يقرع السمع، وتكراره مع الاستفهام يضاعف الهول قبل أي تفصيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص287–293.","url":""}]},{"id":"s101-2","number":2,"surah":101,"verses":[1],"verseLabel":"القارعة: 1","question":"ما دلالة اسم ﴿الْقَارِعَةُ﴾؟","answer":"حادثة تضرب القلوب والأسماع بشدتها، فاختير اسم صوتي حسي للقيامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص287–293.","url":""}]},{"id":"s101-3","number":3,"surah":101,"verses":[4],"verseLabel":"القارعة: 4","question":"لماذا شبه الناس بالفراش المبثوث؟","answer":"الفراش خفيف مضطرب ينتشر بلا جهة حول الضوء؛ صورة للحيرة والكثرة وفقدان النظام.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص294–302.","url":""}]},{"id":"s101-4","number":4,"surah":101,"verses":[5],"verseLabel":"القارعة: 5","question":"لماذا شبهت الجبال بالعهن المنفوش؟","answer":"أثقل ما يراه الإنسان يصير صوفًا خفيفًا متطايرًا؛ فالقيامة تقلب معيار الوزن والثبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص294–302.","url":""}]},{"id":"s101-5","number":5,"surah":101,"verses":[6,7,8,9],"verseLabel":"القارعة: 6–9","question":"كيف قابلت ثقل الموازين بخفتها؟","answer":"جعل الوزن الأخلاقي فاصلاً بين عيشة راضية وهاوية، فليس ثقل الجسد أو المال هو القيمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص303–313.","url":""}]},{"id":"s101-6","number":6,"surah":101,"verses":[7],"verseLabel":"القارعة: 7","question":"لماذا وصفت العيشة بأنها ﴿رَاضِيَةٍ﴾؟","answer":"أسند الرضا إلى العيشة للمبالغة؛ فهي مرضية لصاحبها أو كأنها نفسها راضية به.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص303–313.","url":""}]},{"id":"s101-7","number":7,"surah":101,"verses":[9],"verseLabel":"القارعة: 9","question":"ما الصورة في ﴿فَأُمُّهُ هَاوِيَةٌ﴾؟","answer":"قيل: أمه مأواه الذي يأوي إليه كما يأوي الولد إلى أمه، لكن مأواه الهاوية؛ وقيل: يهوي فيها على أم رأسه. والصورة على الوجهين تبلغ غاية التهويل.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص303–313.","url":""}]},{"id":"s101-8","number":8,"surah":101,"verses":[10,11],"verseLabel":"القارعة: 10–11","question":"لماذا أعيد سؤال ﴿وَمَا أَدْرَاكَ مَا هِيَهْ﴾ ثم قيل ﴿نَارٌ حَامِيَةٌ﴾؟","answer":"أبهم ضمير الهاوية ليعلق الذهن، ثم جاء الجواب القصير الحاسم مع هاء السكت التي تثقل الوقف.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص314–319.","url":""}]},{"id":"s102-1","number":1,"surah":102,"verses":[1],"verseLabel":"التكاثر: 1","question":"ما سرّ التعبير بقوله تعالى ﴿أَلْهَاكُمُ التَّكَاثُرُ﴾ مع عدم ذكر المتكاثَر فيه؟","answer":"ليعم المال والولد والجاه وكل ما يتحول من وسيلة إلى منافسة تصرف عن الغاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص324–333.","url":""}]},{"id":"s102-2","number":2,"surah":102,"verses":[1],"verseLabel":"التكاثر: 1","question":"ما الفرق بين التكاثر والكثرة؟","answer":"الكثرة وصف للعدد، أما التكاثر فسعي تنافسي لطلب الزيادة والمباهاة بها؛ والذم متعلق بالانشغال لا بمجرد النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص324–333.","url":""}]},{"id":"s102-3","number":3,"surah":102,"verses":[2],"verseLabel":"التكاثر: 2","question":"ما الصورة في ﴿حَتَّى زُرْتُمُ الْمَقَابِرَ﴾؟","answer":"يحتمل أن المراد بلوغ القبور بالموت، وسُمّي المكث فيها زيارة لأنه مؤقت يعقبه البعث؛ ويحتمل التفاخر بعدّ الموتى وزيارة قبورهم، فلا يُحصر التعبير في وجه واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص324–333.","url":""}]},{"id":"s102-4","number":4,"surah":102,"verses":[3,4],"verseLabel":"التكاثر: 3–4","question":"لماذا تكرر ﴿كَلَّا سَوْفَ تَعْلَمُونَ﴾؟","answer":"ردع يتبعه وعيد متصاعد؛ قيل للعلم عند الموت ثم عند البعث، أو لتأكيد هول ما سيظهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص334–337.","url":""}]},{"id":"s102-5","number":5,"surah":102,"verses":[5],"verseLabel":"التكاثر: 5","question":"ما دلالة ﴿لَوْ تَعْلَمُونَ عِلْمَ الْيَقِينِ﴾؟","answer":"جواب «لو» محذوف ليذهب الذهن إلى كل ما كان سيمنعهم عنه اليقين، فالحذف أوسع تهويلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص338–349.","url":""}]},{"id":"s102-6","number":6,"surah":102,"verses":[6,7],"verseLabel":"التكاثر: 6–7","question":"لماذا جمعت رؤية الجحيم بعين اليقين؟","answer":"الأولى رؤية محققة بعد الوعيد، والثانية معاينة لا يبقى معها احتمال أو تكذيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص338–349.","url":""}]},{"id":"s102-7","number":7,"surah":102,"verses":[8],"verseLabel":"التكاثر: 8","question":"لماذا ختمت بالسؤال عن النعيم؟","answer":"بعد ذم التكاثر يعاد تعريف المال والصحة والأمن بوصفها أمانات سيسأل الإنسان عن شكرها واستعمالها.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص338–349.","url":""}]},{"id":"s103-1","number":1,"surah":103,"verses":[1],"verseLabel":"العصر: 1","question":"لماذا أقسم بالعصر؟","answer":"قيل: المراد الدهر كله لما يجري فيه من العبر والأعمال، وقيل وقت العصر أو صلاته لشرفها، وقيل عصر النبوة؛ والجامع التنبيه إلى عظم الزمن وما يقع فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص356–383.","url":""}]},{"id":"s103-2","number":2,"surah":103,"verses":[2],"verseLabel":"العصر: 2","question":"ما دلالة التوكيد في ﴿إِنَّ الْإِنْسَانَ لَفِي خُسْرٍ﴾؟","answer":"«إن» واللام و«في» تجعل الخسر محيطًا بالجنس كله، لا خسارة عارضة في جانب واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص356–383.","url":""}]},{"id":"s103-3","number":3,"surah":103,"verses":[2],"verseLabel":"العصر: 2","question":"لماذا أُفرد ﴿الْإِنْسَانَ﴾ والمراد الجنس؟","answer":"المفرد المحلى بـ«أل» يستغرق كل فرد، فيشعر القارئ أن الحكم يتجه إليه شخصيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص356–383.","url":""}]},{"id":"s103-4","number":4,"surah":103,"verses":[3],"verseLabel":"العصر: 3","question":"لماذا جمعت النجاة أربعة أصول: الإيمان والعمل والحق والصبر؟","answer":"الإيمان يصحح الداخل، والعمل يحققه، والتواصي بالحق يصلح الجماعة، والصبر يحفظ الجميع عبر الزمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص356–383.","url":""}]},{"id":"s103-5","number":5,"surah":103,"verses":[3],"verseLabel":"العصر: 3","question":"ما الفرق بين فعل الخير والتواصي به؟","answer":"قد ينجو الفرد بعمله مؤقتًا، لكن المجتمع يحتاج تبادل التذكير؛ «تواصوا» تجعل كل واحد موصيًا ومستوصيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص356–383.","url":""}]},{"id":"s103-6","number":6,"surah":103,"verses":[3],"verseLabel":"العصر: 3","question":"لماذا خُتم بالصبر بعد الحق؟","answer":"لأن معرفة الحق وقوله والعمل به تجلب كلفة ومقاومة، فلا يثبت مساره دون صبر متبادل.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص356–383.","url":""}]},{"id":"s104-1","number":1,"surah":104,"verses":[1],"verseLabel":"الهمزة: 1","question":"ما الفرق بين ﴿هُمَزَةٍ لُمَزَةٍ﴾؟","answer":"قيل الهمز علنًا واللمز خفية، وقيل أحدهما بالقول والآخر بالإشارة مع اختلاف التعيين؛ والجامع الاعتياد على الطعن والازدراء، وهو ما تلائمه صيغتا المبالغة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص390–429.","url":""}]},{"id":"s104-2","number":2,"surah":104,"verses":[1],"verseLabel":"الهمزة: 1","question":"لماذا نُكّر ﴿هُمَزَةٍ لُمَزَةٍ﴾ بعد ﴿كُلِّ﴾؟","answer":"لتعم كل صورة وكل شخص اتصف بها، مع تهويل قبح الصفة ولو اختلف صاحبها.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص390–429.","url":""}]},{"id":"s104-3","number":3,"surah":104,"verses":[2],"verseLabel":"الهمزة: 2","question":"ما دلالة ﴿جَمَعَ مَالًا وَعَدَّدَهُ﴾؟","answer":"لم يكتف بالجمع بل أعاد عده وتفقده؛ صورة تعلق نفسي يجعل المال موضوعًا دائمًا للوعي.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص390–429.","url":""}]},{"id":"s104-4","number":4,"surah":104,"verses":[3],"verseLabel":"الهمزة: 3","question":"ما سرّ التعبير بالماضي في ﴿يَحْسَبُ أَنَّ مَالَهُ أَخْلَدَهُ﴾؟","answer":"يتوهم أن المال قد ضمن الخلود بالفعل، لا أنه سيمنحه لاحقًا؛ فالوهم عنده راسخ حاضر.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص390–429.","url":""}]},{"id":"s104-5","number":5,"surah":104,"verses":[4],"verseLabel":"الهمزة: 4","question":"ما أثر ﴿كَلَّا لَيُنْبَذَنَّ فِي الْحُطَمَةِ﴾؟","answer":"قوبل جمع المال وصونه بأن يُطرح صاحبه نفسه طرح الشيء المهمل، والتوكيد يقطع حلم الخلود.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص390–429.","url":""}]},{"id":"s104-6","number":6,"surah":104,"verses":[4],"verseLabel":"الهمزة: 4","question":"لماذا سميت النار ﴿الْحُطَمَةِ﴾؟","answer":"تحطم ما يلقى فيها، وتناسب من حطم كرامات الناس بلسانه أن يلقى عاقبة من جنس فعله.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص390–429.","url":""}]},{"id":"s104-7","number":7,"surah":104,"verses":[5,6],"verseLabel":"الهمزة: 5–6","question":"لماذا فُخمت الحطمة ثم فسرت بـ﴿نَارُ اللَّهِ الْمُوقَدَةُ﴾؟","answer":"إضافتها إلى الله تعظمها، و«الموقدة» تدل على استمرار الاشتعال لا نار خامدة تنتظر الوقود.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص390–429.","url":""}]},{"id":"s104-8","number":8,"surah":104,"verses":[7],"verseLabel":"الهمزة: 7","question":"ما دلالة ﴿تَطَّلِعُ عَلَى الْأَفْئِدَةِ﴾؟","answer":"تبلغ النار موضع النيات والاحتقار وحب المال؛ فالعقوبة تصل إلى أصل الجريمة الباطن.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص390–429.","url":""}]},{"id":"s104-9","number":9,"surah":104,"verses":[8,9],"verseLabel":"الهمزة: 8–9","question":"لماذا ختمت بالإيصاد والعمد الممددة؟","answer":"أبواب محكمة وأعمدة ممتدة تمنع الانفلات، فتقابل وهم الخلود في المال بخلود محاصر في النار.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص390–429.","url":""}]},{"id":"s105-1","number":1,"surah":105,"verses":[1],"verseLabel":"الفيل: 1","question":"لماذا افتتحت بـ﴿أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ﴾ مع أن النبي لم يشهد الحادثة؟","answer":"العلم المتواتر وخبر الوحي في اليقين كالرؤية، و«كيف» توجه إلى عجيب الصنع لا أصل وقوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص438–469.","url":""}]},{"id":"s105-2","number":2,"surah":105,"verses":[1],"verseLabel":"الفيل: 1","question":"ما دلالة إضافة الرب إلى النبي؟","answer":"تثبيت بأن الذي حمى بيته وأهلك المعتدين هو رب النبي وناصر رسالته.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص438–469.","url":""}]},{"id":"s105-3","number":3,"surah":105,"verses":[2],"verseLabel":"الفيل: 2","question":"ما سرّ التعبير بقوله ﴿أَلَمْ يَجْعَلْ كَيْدَهُمْ فِي تَضْلِيلٍ﴾؟","answer":"لم يبطل الخطة فقط بل جعلها غارقة في الضياع والانحراف عن غايتها؛ انقلب التدبير على أصحابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص438–469.","url":""}]},{"id":"s105-4","number":4,"surah":105,"verses":[3],"verseLabel":"الفيل: 3","question":"ما دلالة ﴿طَيْرًا أَبَابِيلَ﴾؟","answer":"جماعات متتابعة متفرقة تأتي من جهات، فيقابل تعددها جيشًا ضخمًا بأداة تبدو أضعف.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص438–469.","url":""}]},{"id":"s105-5","number":5,"surah":105,"verses":[4],"verseLabel":"الفيل: 4","question":"لماذا جُمع بين طير وحجارة من سجيل؟","answer":"اجتمعت خفة الحامل وصلابة المحمول، ليظهر أن القوة في أمر الله لا في حجم الوسيلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص438–469.","url":""}]},{"id":"s105-6","number":6,"surah":105,"verses":[5],"verseLabel":"الفيل: 5","question":"ما الصورة في ﴿فَجَعَلَهُمْ كَعَصْفٍ مَأْكُولٍ﴾؟","answer":"صار الجيش كورق زرع أكلته الدواب فتمزق؛ تشبيه يجمع التفتت والمهانة وزوال الصورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص438–469.","url":""}]},{"id":"s105-7","number":7,"surah":105,"verses":[1,2,3,4,5],"verseLabel":"الفيل: 1–5","question":"كيف تناسب قصر السورة ضخامة الحدث؟","answer":"خمسة أفعال حاسمة تنقل من الخطة إلى الإرسال والرمي ثم الحطام، فتحاكي سرعة انهيار القوة المعتدية.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص438–469.","url":""}]},{"id":"s106-1","number":1,"surah":106,"verses":[1,2],"verseLabel":"قريش: 1–2","question":"لماذا تكرر ﴿إِيلَافِ﴾ في ﴿لِإِيلَافِ قُرَيْشٍ إِيلَافِهِمْ﴾؟","answer":"الأول يذكر النعمة إجمالًا، والثاني يفسرها برحلة الشتاء والصيف ويؤكد تمكن الألفة والاستمرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص475–493.","url":""}]},{"id":"s106-2","number":2,"surah":106,"verses":[1],"verseLabel":"قريش: 1","question":"ما سر دخول اللام على ﴿لِإِيلَافِ قُرَيْشٍ﴾؟","answer":"تتعلق بما قبلها: أهلك أصحاب الفيل لأجل إيلافهم، أو بما بعدها: فليعبدوا شكرًا لهذه النعمة؛ والمعنيان يصلان السورتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص438–469 وص475–493.","url":""}]},{"id":"s106-3","number":3,"surah":106,"verses":[2],"verseLabel":"قريش: 2","question":"ما سرّ التعبير بـ﴿رِحْلَةَ الشِّتَاءِ وَالصَّيْفِ﴾ بالإفراد؟","answer":"لأن الرحلتين نظام تجاري واحد متكرر، فجمعهما مصدر واحد مع بيان موسميه.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص475–493.","url":""}]},{"id":"s106-4","number":4,"surah":106,"verses":[3],"verseLabel":"قريش: 3","question":"ما دلالة الفاء في ﴿فَلْيَعْبُدُوا﴾؟","answer":"تجعل العبادة نتيجة لازمة للنعم المذكورة: إذا استقر الأمن والرزق فحق المنعم أن يوحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص475–493.","url":""}]},{"id":"s106-5","number":5,"surah":106,"verses":[3],"verseLabel":"قريش: 3","question":"ما سرّ التعبير بقوله ﴿رَبَّ هَذَا الْبَيْتِ﴾؟","answer":"استحضر البيت الذي منحهم المكانة وحُمي في السورة السابقة، ورد قدسيته إلى ربه لا إلى أصنامهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص438–469 وص475–493.","url":""}]},{"id":"s106-6","number":6,"surah":106,"verses":[4],"verseLabel":"قريش: 4","question":"ما سرّ تقديم الإطعام من جوع على الأمن من خوف؟","answer":"لأن السياق بدأ برحلة الرزق، ولأن الجوع حاجة يومية ملازمة، ثم جاء الأمن الذي يحفظ الرحلة والبيت.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص475–493.","url":""}]},{"id":"s106-7","number":7,"surah":106,"verses":[4],"verseLabel":"قريش: 4","question":"ما دلالة تنكير ﴿جُوعٍ﴾ و﴿خَوْفٍ﴾؟","answer":"يصور شدة أي جوع وأي خوف أنقذهم الله منهما، ويمنع حصر النعمة في واقعة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص475–493.","url":""}]},{"id":"s106-8","number":8,"surah":106,"verses":[1],"verseLabel":"قريش: الفيل–قريش","question":"ما العلاقة البيانية بين سورتي الفيل وقريش؟","answer":"الفيل تعرض دفع الضرر عن البيت، وقريش تعرض جلب منفعة الأمن والرزق لأهله؛ فتمت النعمة بوجهيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص438–469 وص475–493.","url":""}]},{"id":"s107-1","number":1,"surah":107,"verses":[1],"verseLabel":"الماعون: 1","question":"لماذا افتتحت بـ﴿أَرَأَيْتَ الَّذِي يُكَذِّبُ بِالدِّينِ﴾؟","answer":"تثير فضول السامع ثم لا تعرف المكذب باسمه بل بسلوكه، لتجعل الدين ظاهرًا في معاملة الضعفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص501–525.","url":""}]},{"id":"s107-2","number":2,"surah":107,"verses":[2],"verseLabel":"الماعون: 2","question":"ما دلالة ﴿يَدُعُّ الْيَتِيمَ﴾؟","answer":"الدع دفع بعنف، فهو لا يهمل اليتيم فحسب بل يهينه ويطرده، فكشف اللفظ قسوة القلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص501–525.","url":""}]},{"id":"s107-3","number":3,"surah":107,"verses":[3],"verseLabel":"الماعون: 3","question":"ما سرّ التعبير بقوله ﴿لَا يَحُضُّ عَلَى طَعَامِ الْمِسْكِينِ﴾؟","answer":"ذمه حتى على ترك الحث ولو لم يملك الطعام؛ فالمجتمع مسؤول عن صناعة إرادة التكافل.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص501–525.","url":""}]},{"id":"s107-4","number":4,"surah":107,"verses":[3],"verseLabel":"الماعون: 3","question":"لماذا أضيف الطعام إلى المسكين؟","answer":"كأنه حقه الذي حُبس عنه لا منّة من الغني، فتتغير زاوية الملكية الأخلاقية.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص501–525.","url":""}]},{"id":"s107-5","number":5,"surah":107,"verses":[4],"verseLabel":"الماعون: 4","question":"ما المفارقة في ﴿فَوَيْلٌ لِلْمُصَلِّينَ﴾؟","answer":"يوقف السامع مفزوعًا ثم يقيده بمن سها ورياءً؛ فليس الوعيد للصلاة بل لصورتها الفارغة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص501–525.","url":""}]},{"id":"s107-6","number":6,"surah":107,"verses":[5],"verseLabel":"الماعون: 5","question":"ما الفرق بين السهو عن الصلاة والسهو فيها؟","answer":"السهو عنها إضاعة لها أو لوقتها وعدم مبالاة، أما العارض داخلها فطبيعة بشرية لا يقصدها هذا الوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص501–525.","url":""}]},{"id":"s107-7","number":7,"surah":107,"verses":[6],"verseLabel":"الماعون: 6","question":"ما دلالة صيغة الجمع والمضارع في ﴿يُرَاءُونَ﴾؟","answer":"يصوّر الرياء عادة متجددة تُوجَّه للناس، فيقابل غياب الإخلاص في العبادة غياب الرحمة في المعاملة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص501–525.","url":""}]},{"id":"s107-8","number":8,"surah":107,"verses":[7],"verseLabel":"الماعون: 7","question":"ما سعة ﴿الْمَاعُونَ﴾؟","answer":"كل نفع قليل يتعاوره الناس من إناء وأداة وماء وزكاة؛ ومنعه يكشف أن البخل بلغ أبسط المعروف.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص501–525.","url":""}]},{"id":"s107-9","number":9,"surah":107,"verses":[1,2,3,4,5,6,7],"verseLabel":"الماعون: 1–7","question":"كيف ربطت السورة التكذيب بالدين بالرياء ومنع الماعون؟","answer":"بيّنت أن إنكار الحساب ليس فكرة ذهنية فقط؛ يظهر في قهر الضعيف وعبادة السمعة وقطع النفع اليومي.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص501–525.","url":""}]},{"id":"s108-1","number":1,"surah":108,"verses":[1],"verseLabel":"الكوثر: 1","question":"لماذا افتتحت بـ﴿إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ﴾ بهذا التوكيد؟","answer":"جاءت ردًا على من زعم انقطاع النبي؛ فأكد العطاء وأسنده إلى ضمير العظمة وجعله منجزًا بالماضي.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص534–555.","url":""}]},{"id":"s108-2","number":2,"surah":108,"verses":[1],"verseLabel":"الكوثر: 1","question":"ما دلالة اختيار ﴿أَعْطَيْنَاكَ﴾ لا «آتيناك»؟","answer":"العطاء يبرز التمليك والتفضل المباشر، ويلائم خيرًا خالصًا كثيرًا مختصًا بالنبي.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص534–555.","url":""}]},{"id":"s108-3","number":3,"surah":108,"verses":[1],"verseLabel":"الكوثر: 1","question":"ما سعة معنى ﴿الْكَوْثَرَ﴾؟","answer":"خير كثير متنامٍ يشمل نهر الجنة والنبوة والقرآن وكثرة الأتباع ودوام الذكر؛ فلا يحصره مظهر واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص534–555.","url":""}]},{"id":"s108-4","number":4,"surah":108,"verses":[2],"verseLabel":"الكوثر: 2","question":"لماذا رُتبت الصلاة ثم النحر؟","answer":"جمع أشرف عبادة بدنية وأشرف بذل مالي، وجعلهما شكرًا عمليًا على الكوثر.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص534–555.","url":""}]},{"id":"s108-5","number":5,"surah":108,"verses":[2],"verseLabel":"الكوثر: 2","question":"ما دلالة ﴿لِرَبِّكَ﴾؟","answer":"تقديم الاختصاص يخلص الصلاة والذبح لله، فيقابل عبادات المشركين وذبائحهم لغيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص534–555.","url":""}]},{"id":"s108-6","number":6,"surah":108,"verses":[3],"verseLabel":"الكوثر: 3","question":"ما سرّ التعبير بقوله ﴿إِنَّ شَانِئَكَ هُوَ الْأَبْتَرُ﴾؟","answer":"ضمير الفصل وتعريف الأبتر يقصران الانقطاع الحقيقي على مبغض النبي، فقلبت السورة التهمة على قائلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص534–555.","url":""}]},{"id":"s108-7","number":7,"surah":108,"verses":[3],"verseLabel":"الكوثر: 3","question":"ما الفرق بين «مبغضك» و﴿شَانِئَكَ﴾؟","answer":"الشنآن بغض شديد يظهر أثره، فناسب من حمله حقده على الشماتة بموت أبناء النبي.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص534–555.","url":""}]},{"id":"s108-8","number":8,"surah":108,"verses":[1,2,3],"verseLabel":"الكوثر: 1–3","question":"كيف تقابل أول السورة وآخرها؟","answer":"الكوثر كثرة فائضة للنبي، والأبتر انقطاع لشانئه؛ فبنيت السورة كلها على مقابلة العطاء والزوال.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص534–555.","url":""}]},{"id":"s109-1","number":1,"surah":109,"verses":[1],"verseLabel":"الكافرون: 1","question":"لماذا بدأ بـ﴿قُلْ يَا أَيُّهَا الْكَافِرُونَ﴾ بهذا النداء الصريح؟","answer":"المقام مقام مفاصلة بعد عرض المساومة، فسمى موقفهم العقدي بلا مداهنة وأمر النبي بإعلانه وحيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص562–587.","url":""}]},{"id":"s109-2","number":2,"surah":109,"verses":[2,3,4,5],"verseLabel":"الكافرون: 2–5","question":"لماذا تكرر نفي العبادة أربع مرات؟","answer":"يفصل الحاضر والمستقبل، وينفي اختلاف المعبود واختلاف طريقة العبادة؛ فلا اتفاق عابر ولا اندماج عقدي.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص562–587.","url":""}]},{"id":"s109-3","number":3,"surah":109,"verses":[2,4],"verseLabel":"الكافرون: 2، 4","question":"ما الفرق بين ﴿لَا أَعْبُدُ﴾ و﴿وَلَا أَنَا عَابِدٌ﴾؟","answer":"الفعل ينفي وقوع العبادة، واسم الفاعل ينفي ثبوت الصفة والاتصاف بها؛ فاجتمع نفي الفعل والهوية.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص562–587.","url":""}]},{"id":"s109-4","number":4,"surah":109,"verses":[2,3],"verseLabel":"الكافرون: 2–3","question":"ما سرّ التعبير أولًا بـ﴿مَا تَعْبُدُونَ﴾ ثم بـ﴿مَا أَعْبُدُ﴾؟","answer":"غلبت «ما» في معبوداتهم لأنها أصنام، وتأتي للعاقل عند أمن اللبس، ويحتمل أن يراد بها الصفة أو طريقة العبادة؛ فاستقام تقابل العبارتين من غير إيهام اتحاد المعبود أو العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص562–587.","url":""}]},{"id":"s109-5","number":5,"surah":109,"verses":[3,5],"verseLabel":"الكافرون: 3، 5","question":"لماذا تكرر ﴿وَلَا أَنْتُمْ عَابِدُونَ مَا أَعْبُدُ﴾؟","answer":"الأولى لحالهم، والثانية لتقرير رسوخ طريقهم ما داموا على الكفر، أو لتأكيد اختلاف الكيفية فضلًا عن المعبود.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص562–587.","url":""}]},{"id":"s109-6","number":6,"surah":109,"verses":[6],"verseLabel":"الكافرون: 6","question":"هل ﴿لَكُمْ دِينُكُمْ وَلِيَ دِينِ﴾ إقرار بصحة الأديان؟","answer":"لا؛ هو إعلان براءة ومفاصلة وترك للجزاء إلى الله، لا تسوية بين الحق والباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص562–587.","url":""}]},{"id":"s109-7","number":7,"surah":109,"verses":[6],"verseLabel":"الكافرون: 6","question":"ما سرّ تقديم ﴿لَكُمْ﴾ و﴿لِيَ﴾؟","answer":"للاختصاص والفصل: تبعة دينكم لكم، وديني خالص لي، فلا مساحة للمساومة التي اقترحوها.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص562–587.","url":""}]},{"id":"s110-1","number":1,"surah":110,"verses":[1],"verseLabel":"النصر: 1","question":"لماذا افتتحت بـ﴿إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ﴾؟","answer":"«إذا» تستحضر حدثًا محققًا، وإضافة النصر إلى الله تنزع الفضل من القوة البشرية.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص593–619.","url":""}]},{"id":"s110-2","number":2,"surah":110,"verses":[1],"verseLabel":"النصر: 1","question":"ما الفرق بين النصر والفتح؟","answer":"النصر تأييد وغلبة، والفتح ثمرة ظاهرة تزيل المانع وتفتح البلد والقلوب؛ فذكر السبب والنتيجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص593–619.","url":""}]},{"id":"s110-3","number":3,"surah":110,"verses":[2],"verseLabel":"النصر: 2","question":"ما سرّ التعبير بقوله ﴿يَدْخُلُونَ فِي دِينِ اللَّهِ أَفْوَاجًا﴾؟","answer":"«في» تصور دخولًا تامًا، والأفواج جماعات متتابعة تقابل سنوات دخول الأفراد واحدًا واحدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص593–619.","url":""}]},{"id":"s110-4","number":4,"surah":110,"verses":[2],"verseLabel":"النصر: 2","question":"ما دلالة المضارع ﴿يَدْخُلُونَ﴾ بعد مجيء الفتح؟","answer":"يستحضر المشهد المتجدد ويرسم استمرار وفود القبائل بعد تحقق السبب.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص593–619.","url":""}]},{"id":"s110-5","number":5,"surah":110,"verses":[3],"verseLabel":"النصر: 3","question":"لماذا كان جواب النصر التسبيح والاستغفار؟","answer":"التسبيح ينزه الله وينسب الكمال إليه، والحمد يشكر النعمة، والاستغفار يطهر العبد من رؤية نفسه في النجاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص593–619.","url":""}]},{"id":"s110-6","number":6,"surah":110,"verses":[3],"verseLabel":"النصر: 3","question":"ما دلالة ﴿بِحَمْدِ رَبِّكَ﴾؟","answer":"تسبيح مصاحب للحمد لا مجرد نفي للنقص؛ وإضافة الرب تذكر بالرعاية التي أوصلت الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص593–619.","url":""}]},{"id":"s110-7","number":7,"surah":110,"verses":[3],"verseLabel":"النصر: 3","question":"ما سرّ التعبير بقوله ﴿إِنَّهُ كَانَ تَوَّابًا﴾؟","answer":"«توابًا» صيغة مبالغة تلائم كثرة من يدخلون ويتوبون وكثرة رجوع العبد إلى ربه، و«كان» تثبت دوام الصفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص593–619.","url":""}]},{"id":"s110-8","number":8,"surah":110,"verses":[1],"verseLabel":"النصر: السورة","question":"كيف حملت السورة بشارة النصر وإشارة الوداع معًا؟","answer":"اكتمال دخول الناس علامة تمام المهمة، ففهم النبي أن ما بعد تمام البلاغ استعداد للقاء بالتسبيح والاستغفار.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص593–619.","url":""}]},{"id":"s111-1","number":1,"surah":111,"verses":[1],"verseLabel":"المسد: 1","question":"لماذا بدأت بـ﴿تَبَّتْ يَدَا أَبِي لَهَبٍ وَتَبَّ﴾؟","answer":"اليدان كناية عن العمل والقوة، ثم عُمم الهلاك على صاحبه؛ فخسر سعيه وذاته.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص626–656.","url":""}]},{"id":"s111-2","number":2,"surah":111,"verses":[1],"verseLabel":"المسد: 1","question":"ما الفرق بين ﴿تَبَّتْ﴾ الأولى و﴿وَتَبَّ﴾ الثانية؟","answer":"الأولى دعاء أو خبر على اليدين والعمل، والثانية تقرير وقوع الهلاك لصاحبه كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص626–656.","url":""}]},{"id":"s111-3","number":3,"surah":111,"verses":[1,3],"verseLabel":"المسد: 1، 3","question":"ما المفارقة بين كنية ﴿أَبِي لَهَبٍ﴾ و﴿نَارًا ذَاتَ لَهَبٍ﴾؟","answer":"الاسم الذي قد يوحي بالسطوع والاعتزاز صار مناسبًا لعقوبته، فقلب اللفظ فخره إلى وعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص626–656.","url":""}]},{"id":"s111-4","number":4,"surah":111,"verses":[2],"verseLabel":"المسد: 2","question":"لماذا نُفي نفع المال والكسب؟","answer":"جمع ما يملكه وما حصله أو ولده، ليقرر أن أدوات القوة الاجتماعية كلها لا تدفع حكم الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص626–656.","url":""}]},{"id":"s111-5","number":5,"surah":111,"verses":[3],"verseLabel":"المسد: 3","question":"ما دلالة السين في ﴿سَيَصْلَى نَارًا﴾؟","answer":"السين للاستقبال والوعيد المحقق، وفي الإخبار بمصيره وهو حي ثم موته على الكفر شاهد صدق للوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص626–656.","url":""}]},{"id":"s111-6","number":6,"surah":111,"verses":[4],"verseLabel":"المسد: 4","question":"لماذا ذُكرت امرأته معه؟","answer":"لأنها شاركته العداوة قولًا وعملًا، فانتقلت السورة من مسؤولية الزوج إلى مسؤوليتها الشخصية.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص626–656.","url":""}]},{"id":"s111-7","number":7,"surah":111,"verses":[4],"verseLabel":"المسد: 4","question":"ما دلالة ﴿حَمَّالَةَ الْحَطَبِ﴾؟","answer":"حقيقة فيما كانت تحمل أو كناية عن نقل النميمة وإيقاد الفتنة؛ والصورتان تجمعان تغذية الأذى.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص626–656.","url":""}]},{"id":"s111-8","number":8,"surah":111,"verses":[5],"verseLabel":"المسد: 5","question":"ما مناسبة ﴿حَبْلٌ مِنْ مَسَدٍ﴾ لعنقها؟","answer":"من حملت الحطب وربطته يُجعل الحبل نفسه علامة هوان وعذاب؛ جزاء يصور جنس فعلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص626–656.","url":""}]},{"id":"s112-1","number":1,"surah":112,"verses":[1],"verseLabel":"الإخلاص: 1","question":"لماذا افتتحت بـ﴿قُلْ﴾؟","answer":"العقيدة الموجزة جواب وحي مأمور بإعلانه، لا تأملًا بشريًا قابلًا للمساومة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص665–688.","url":""}]},{"id":"s112-2","number":2,"surah":112,"verses":[1],"verseLabel":"الإخلاص: 1","question":"ما دلالة ﴿هُوَ اللَّهُ أَحَدٌ﴾؟","answer":"«هو» يوجه إلى المسؤول عنه، واسم الجلالة يجمع صفات الكمال، و«أحد» ينفي كل تركيب وشريك ومثيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص665–688.","url":""}]},{"id":"s112-3","number":3,"surah":112,"verses":[1],"verseLabel":"الإخلاص: 1","question":"ما سرّ التعبير بـ﴿أَحَدٌ﴾ دون «واحد»؟","answer":"الأحد في هذا الإثبات يدل على الوحدانية المطلقة التي لا تقبل التجزؤ ولا النظير، وهو أخص بالمقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص665–688.","url":""}]},{"id":"s112-4","number":4,"surah":112,"verses":[2],"verseLabel":"الإخلاص: 2","question":"ما سعة اسم ﴿الصَّمَدُ﴾؟","answer":"السيد الكامل المقصود في الحوائج المستغني عن الجميع، فبعد نفي الشريك أثبت كمال الغنى والافتقار إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص665–688.","url":""}]},{"id":"s112-5","number":5,"surah":112,"verses":[2],"verseLabel":"الإخلاص: 2","question":"لماذا عُرّف ﴿اللَّهُ الصَّمَدُ﴾؟","answer":"التعريف يفيد أنه الكامل المعروف بالصمدية وحده، والجملة الاسمية تثبت الصفة بلا زمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص665–688.","url":""}]},{"id":"s112-6","number":6,"surah":112,"verses":[3],"verseLabel":"الإخلاص: 3","question":"ما سرّ تقديم ﴿لَمْ يَلِدْ﴾ على ﴿وَلَمْ يُولَدْ﴾؟","answer":"بدأ بنفي الدعوى الأشهر التي نسبها المشركون إليه، ثم نفى أن يكون هو متولدًا محتاجًا إلى أصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص665–688.","url":""}]},{"id":"s112-7","number":7,"surah":112,"verses":[3],"verseLabel":"الإخلاص: 3","question":"ما الفرق البياني بين نفي الولادة ونفي الوالدية؟","answer":"نفي أن يلد يقطع الفرع والمماثل، ونفي أن يولد يقطع الأصل والحدوث؛ فأحاط النفي بجهتي النسب.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص665–688.","url":""}]},{"id":"s112-8","number":8,"surah":112,"verses":[4],"verseLabel":"الإخلاص: 4","question":"ما سرّ تقديم ﴿لَهُ﴾ في ﴿وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ﴾؟","answer":"لقصر نفي المكافئ عليه والاهتمام به، ولتأتي الفاصلة بـ«أحد» فترد على «أحد» المطلع.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص665–688.","url":""}]},{"id":"s112-9","number":9,"surah":112,"verses":[1,4],"verseLabel":"الإخلاص: 1، 4","question":"كيف تعانق لفظ ﴿أَحَدٌ﴾ في أول السورة وآخرها؟","answer":"الأول يثبت وحدانيته، والآخر ينفي أن يوجد أي أحد مكافئ له؛ إثبات الكمال ثم نفي المثل.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص665–688.","url":""}]},{"id":"s112-10","number":10,"surah":112,"verses":[1],"verseLabel":"الإخلاص: السورة","question":"كيف جمعت السورة التوحيد في أربع آيات؟","answer":"أثبتت الذات الواحدة والصمدية، ثم نفت الأصل والفرع، ثم نفت النظير؛ فجمعت الإثبات والتنزيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص665–688.","url":""}]},{"id":"s113-1","number":1,"surah":113,"verses":[1],"verseLabel":"الفلق: 1","question":"لماذا افتتحت بـ﴿قُلْ أَعُوذُ﴾؟","answer":"تعليم عملي للاستعاذة بلفظ يعلنه اللسان ويحضره القلب؛ فطلب الحماية نفسه وحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص695–716.","url":""}]},{"id":"s113-2","number":2,"surah":113,"verses":[1],"verseLabel":"الفلق: 1","question":"ما دلالة اختيار ﴿بِرَبِّ الْفَلَقِ﴾؟","answer":"الفلق الصبح المنفلق من الظلمة، وقيل كل ما فلقه الله وأخرجه إلى الوجود؛ والرب القادر على إظهار النور وإيجاد المفلوقات قادر على دفع الشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص695–716.","url":""}]},{"id":"s113-3","number":3,"surah":113,"verses":[2],"verseLabel":"الفلق: 2","question":"لماذا بدأ بالاستعاذة ﴿مِنْ شَرِّ مَا خَلَقَ﴾؟","answer":"قاعدة عامة تستوعب كل شر في المخلوقات، ثم تأتي الأنواع الخاصة لشدة خفائها أو وقوعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص695–716.","url":""}]},{"id":"s113-4","number":4,"surah":113,"verses":[2],"verseLabel":"الفلق: 2","question":"هل في قوله ﴿مِنْ شَرِّ مَا خَلَقَ﴾ نسبة الشر إلى الخلق كله؟","answer":"لا؛ استعاذ من الشر الموجود في بعض المخلوقات أو أحوالها، لا من كل ما خلق، فالشر مقيد لا شامل.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص695–716.","url":""}]},{"id":"s113-5","number":5,"surah":113,"verses":[3],"verseLabel":"الفلق: 3","question":"لماذا قيد شر الغاسق بـ﴿إِذَا وَقَبَ﴾؟","answer":"ليس الليل شرًا في ذاته؛ إنما يُخشى ما ينتشر عند اشتداد ظلمته ودخوله، فجاء القيد للوقت والحال.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص695–716.","url":""}]},{"id":"s113-6","number":6,"surah":113,"verses":[3],"verseLabel":"الفلق: 3","question":"ما الصورة في ﴿غَاسِقٍ إِذَا وَقَبَ﴾؟","answer":"ظلام يتدفق ويدخل في الأشياء والمنافذ، فيجسد انتقال الخطر تحت ستر الليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص695–716.","url":""}]},{"id":"s113-7","number":7,"surah":113,"verses":[4],"verseLabel":"الفلق: 4","question":"لماذا عُرّفت ﴿النَّفَّاثَاتِ فِي الْعُقَدِ﴾ بصيغة المبالغة؟","answer":"تصور تكرر فعل السحر والإفساد وخفاءه، لا نفثة عارضة لا قصد فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص695–716.","url":""}]},{"id":"s113-8","number":8,"surah":113,"verses":[5],"verseLabel":"الفلق: 5","question":"لماذا خُص الحاسد بحال ﴿إِذَا حَسَدَ﴾؟","answer":"قد يحمل الإنسان خاطر الحسد ولا يعمل به؛ الشر الأخطر حين يتحول الباطن إلى إرادة وسعي للإزالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص695–716.","url":""}]},{"id":"s113-9","number":9,"surah":113,"verses":[2,3,4,5],"verseLabel":"الفلق: 2–5","question":"ما نظام الانتقال من الشر العام إلى الغاسق والسحر والحسد؟","answer":"بدأ بالمحيط العام، ثم خطر زماني خفي، ثم أذى مصنوع، ثم دافع نفسي؛ من الخارج إلى أعمق باطن.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص695–716.","url":""}]},{"id":"s113-10","number":10,"surah":113,"verses":[1],"verseLabel":"الفلق: الفلق–الناس","question":"كيف تتكامل المعوذتان؟","answer":"الفلق تستعيذ غالبًا من شرور خارجية وأفعال مؤذية، والناس من الشر الباطن الذي يوسوس في الصدور.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص695–716 وص722–749.","url":""}]},{"id":"s114-1","number":1,"surah":114,"verses":[1,2,3],"verseLabel":"الناس: 1–3","question":"لماذا تكرر ﴿النَّاسِ﴾ مع رب وملك وإله؟","answer":"كل اسم يعالج جهة من الافتقار: الرب يربي، والملك يحكم، والإله يُعبد؛ والتكرار يعظم تعلق البشر به.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص722–749.","url":""}]},{"id":"s114-2","number":2,"surah":114,"verses":[1,2,3],"verseLabel":"الناس: 1–3","question":"لماذا رُتبت الصفات ﴿رَبِّ النَّاسِ مَلِكِ النَّاسِ إِلَهِ النَّاسِ﴾؟","answer":"تدرج من الرعاية القريبة إلى السلطان العام ثم غاية التوحيد والعبادة؛ معرفة تقود إلى خضوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص722–749.","url":""}]},{"id":"s114-3","number":3,"surah":114,"verses":[1],"verseLabel":"الناس: 1","question":"لماذا أضيف الرب إلى الناس خاصة؟","answer":"لأن المستعيذ إنسان يطلب تربية وحفظًا من خطر يدخل قلبه، فناسب ذكر رب النوع المحتاج.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص722–749.","url":""}]},{"id":"s114-4","number":4,"surah":114,"verses":[4],"verseLabel":"الناس: 4","question":"ما دلالة ﴿الْوَسْوَاسِ الْخَنَّاسِ﴾؟","answer":"وسواس كثير الإلقاء الخفي، خناس يتراجع عند الذكر؛ جمع إلحاح الهجوم وإمكان دفعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص722–749.","url":""}]},{"id":"s114-5","number":5,"surah":114,"verses":[4],"verseLabel":"الناس: 4","question":"لماذا عُرّف الوسواس ووُصف بالخناس؟","answer":"ليعين العدو المعروف بفعله وعادته، فلا يبقى الشر فكرة مبهمة بلا طريقة مقاومة.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص722–749.","url":""}]},{"id":"s114-6","number":6,"surah":114,"verses":[5],"verseLabel":"الناس: 5","question":"ما سرّ التعبير بـ﴿فِي صُدُورِ النَّاسِ﴾ دون «قلوبهم»؟","answer":"الصدر ساحة أوسع ترد إليها الخواطر قبل استقرارها في القلب؛ فالوسوسة محاولة اقتحام لا حكم لازم.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص722–749.","url":""}]},{"id":"s114-7","number":7,"surah":114,"verses":[5],"verseLabel":"الناس: 5","question":"ما دلالة المضارع ﴿يُوَسْوِسُ﴾؟","answer":"يصور الفعل متجددًا متكررًا، فيحتاج إلى استعاذة وذكر متجددين.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص722–749.","url":""}]},{"id":"s114-8","number":8,"surah":114,"verses":[6],"verseLabel":"الناس: 6","question":"لماذا ختمت بـ﴿مِنَ الْجِنَّةِ وَالنَّاسِ﴾؟","answer":"تكشف أن الوسوسة قد تأتي من شيطان الجن أو من بشر يزين الباطل، فلا يحصر المؤمن الخطر في غير المرئي.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص722–749.","url":""}]},{"id":"s114-9","number":9,"surah":114,"verses":[1,2,3,4,5,6],"verseLabel":"الناس: 1–6","question":"لماذا بدأت السورة بالمستعاذ به ثلاث مرات وذكرت المستعاذ منه مرة؟","answer":"قوة الحماية مفصلة في ثلاث صفات، أما العدو فمهما خفي ضعيف أمام الرب الملك الإله.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص722–749.","url":""}]},{"id":"s114-10","number":10,"surah":114,"verses":[1],"verseLabel":"الناس: الفاتحة–الناس","question":"ما المناسبة بين خاتمة المصحف وبدايته؟","answer":"الفاتحة استعانة برب العالمين لطلب الصراط، والناس استعاذة برب الناس من صارف الصراط؛ فالبداية هداية والخاتمة حماية.","sources":[{"label":"موسوعة التفسير البلاغي، ج68، ص722–749.","url":""}]}]);
